import React, { useEffect, useState } from 'react';

const BG_OFF = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/home_bg_dimm.png";
const BG_ON = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/home_bg_lit.jpg";

export const BackgroundAmbience: React.FC = () => {
  const [litOpacity, setLitOpacity] = useState(0);

  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout>;

    const scheduleAnimation = () => {
      // 1. Wait random time (40-60s)
      const waitTime = Math.floor(Math.random() * (60000 - 40000 + 1) + 40000);

      console.log(`[Ambience] Waiting ${waitTime/1000}s before lighting up.`);

      timeoutId = setTimeout(() => {
        // 2. Fade In (handled by CSS transition)
        setLitOpacity(1);

        // 3. Hold for random time (40-60s)
        const activeTime = Math.floor(Math.random() * (60000 - 40000 + 1) + 40000);
        console.log(`[Ambience] Runes lit for ${activeTime/1000}s.`);

        timeoutId = setTimeout(() => {
          // 4. Fade Out
          setLitOpacity(0);

          // 5. Schedule next cycle after fade out matches transition time (2s)
          timeoutId = setTimeout(scheduleAnimation, 2000);
        }, activeTime);

      }, waitTime);
    };

    // Initial delay before first cycle
    timeoutId = setTimeout(scheduleAnimation, 1000);

    return () => clearTimeout(timeoutId);
  }, []);

  return (
    <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none bg-slate-950">
      {/* Layer 1: Base (Dimmed/Off) */}
      <div 
        className="absolute inset-0 bg-cover bg-center bg-no-repeat transition-transform duration-[20s] ease-in-out hover:scale-105"
        style={{ backgroundImage: `url(${BG_OFF})` }}
      />

      {/* Layer 2: Active (Lit/On) Container */}
      <div 
        className="absolute inset-0 transition-opacity duration-[2000ms] ease-in-out"
        style={{ opacity: litOpacity }}
      >
         {/* Inner Layer: Handles the flickering (breathing) effect while active */}
         <div 
           className="absolute inset-0 bg-cover bg-center bg-no-repeat animate-pulse-slow"
           style={{ backgroundImage: `url(${BG_ON})` }}
         />
      </div>

      {/* Overlay Gradient for better text readability */}
      <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/60 to-slate-950/20" />
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;
  signIn: () => Promise<void>;
  signOut: () => Promise<void>;
  triggerAdminSequence: () => void;
  checkAdminCode: (code: string) => boolean; // Added missing method
  logoutAdmin: () => void; // Added missing method
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null); // Default to null (Not logged in)
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Secret Sequence State
  const [isListeningForCode, setIsListeningForCode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SECRET_PASS = "admin123";

  const triggerAdminSequence = () => {
    if (isAdmin) return;
    console.log("[System] Identity verification sequence initiated...");
    setIsListeningForCode(true);
    setInputBuffer("");

    setTimeout(() => {
      setIsListeningForCode(false);
      setInputBuffer("");
    }, 5000);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isListeningForCode) return;

      const newBuffer = inputBuffer + e.key;
      setInputBuffer(newBuffer);

      if (newBuffer.includes(SECRET_PASS)) {
        setIsAdmin(true);
        setIsListeningForCode(false);
        console.log("[System] Admin Access Granted.");
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isListeningForCode, inputBuffer]);

  const signIn = async () => {
    setIsLoading(true);
    // Mock login delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    setUser({
        id: '12345',
        email: 'traveller@vk.com',
        role: 'user'
    });
    setIsLoading(false);
  };

  const signOut = async () => {
    setIsLoading(true);
    setIsAdmin(false);
    await new Promise(resolve => setTimeout(resolve, 500));
    setUser(null);
    setIsLoading(false);
  };

  const checkAdminCode = (code: string) => {
    if (code === SECRET_PASS) {
      setIsAdmin(true);
      return true;
    }
    return false;
  };

  const logoutAdmin = () => {
    setIsAdmin(false);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated: !!user, 
      isLoading, 
      isAdmin,
      signIn, 
      signOut,
      triggerAdminSequence,
      checkAdminCode,
      logoutAdmin
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

