import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';
import { supabase } from '../lib/supabase';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;
  signIn: (email?: string, password?: string) => Promise<void>;
  signInAsGuest: () => Promise<void>;
  signOut: () => Promise<void>;
  triggerAdminSequence: () => void;
  checkAdminCode: (code: string) => boolean; 
  logoutAdmin: () => void; 
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null); 
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Secret Sequence State
  const [isListeningForCode, setIsListeningForCode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SECRET_PASS = "admin123";

  // Check admin role from DB
  const checkProfileRole = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', userId)
        .single();

      if (!error && data && data.role === 'admin') {
        setIsAdmin(true);
        console.log("[Auth] Admin privileges confirmed via profile.");
      } else {
        setIsAdmin(false);
      }
    } catch (e) {
      console.error("Error checking profile role:", e);
      setIsAdmin(false);
    }
  };

  const triggerAdminSequence = () => {
    if (isAdmin) return;
    console.log("[System] Identity verification sequence initiated...");
    setIsListeningForCode(true);
    setInputBuffer("");

    setTimeout(() => {
      setIsListeningForCode(false);
      setInputBuffer("");
    }, 5000);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isListeningForCode) return;

      const newBuffer = inputBuffer + e.key;
      setInputBuffer(newBuffer);

      if (newBuffer.includes(SECRET_PASS)) {
        setIsAdmin(true);
        setIsListeningForCode(false);
        console.log("[System] Admin Access Granted via Override.");
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isListeningForCode, inputBuffer]);

  const signIn = async (email?: string, password?: string) => {
    setIsLoading(true);
    try {
        if (email && password) {
            // Attempt real Supabase Auth
            const { data, error } = await supabase.auth.signInWithPassword({ email, password });

            if (error) {
                // For demo purposes/fallback if auth not fully configured in backend yet, 
                // we simulate user login if it fails but we want to allow access.
                // In production, throw error here.
                console.warn("Supabase Auth failed, using fallback/demo user.", error);

                // Demo User
                const demoUser = {
                    id: '12345',
                    email: email,
                    role: 'user' as const
                };
                setUser(demoUser);
                // Can't check profile for demo user easily without real ID, skip admin check
            } else if (data.user) {
                // Real User
                const realUser = {
                    id: data.user.id,
                    email: data.user.email || '',
                    role: 'user' as const
                };
                setUser(realUser);
                await checkProfileRole(data.user.id);
            }
        } else {
            // Legacy / Default mock
            setUser({
                id: '12345',
                email: 'traveller@vk.com',
                role: 'user'
            });
        }
    } catch (e) {
        console.error(e);
    } finally {
        setIsLoading(false);
    }
  };

  const signInAsGuest = async () => {
      setIsLoading(true);
      await new Promise(resolve => setTimeout(resolve, 800)); // Fake loading
      setUser({
          id: 'guest',
          email: 'guest@void.net',
          role: 'guest'
      });
      setIsAdmin(false); // Guests are never admins
      setIsLoading(false);
  };

  const signOut = async () => {
    setIsLoading(true);
    setIsAdmin(false);
    await supabase.auth.signOut();
    await new Promise(resolve => setTimeout(resolve, 500));
    setUser(null);
    setIsLoading(false);
  };

  const checkAdminCode = (code: string) => {
    if (code === SECRET_PASS) {
      setIsAdmin(true);
      return true;
    }
    return false;
  };

  const logoutAdmin = () => {
    setIsAdmin(false);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated: !!user, 
      isLoading, 
      isAdmin,
      signIn, 
      signInAsGuest,
      signOut,
      triggerAdminSequence,
      checkAdminCode,
      logoutAdmin
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

