// Admin Tree Component with Selection support
const AdminCategoryTree = ({ 
    items, 
    parentId = null, 
    level = 0, 
    onEdit, 
    onDelete,
    onSelect,
    selectedId,
    excludeId
}: { 
    items: any[], 
    parentId?: string | number | null, 
    level?: number,
    onEdit?: (item: any) => void,
    onDelete?: (id: string | number) => void,
    onSelect?: (id: string | number | null) => void,
    selectedId?: string | number | null,
    excludeId?: string | number
}) => {
    const children = items.filter(i => i.parent_id === parentId);

    if (children.length === 0) return null;

    return (
        <div className={`space-y-1 ${level > 0 ? 'ml-4 border-l border-white/5 pl-2' : ''}`}>
            {children.map(item => {
                // Don't render the excluded node or its children (circular dependency prevention)
                if (excludeId && String(item.id) === String(excludeId)) return null;

                const isSelected = selectedId && String(selectedId) === String(item.id);

                return (
                <div key={item.id}>
                    <div 
                        className={`flex items-center gap-2 p-2 rounded group transition-colors cursor-pointer ${isSelected ? 'bg-violet-900/40 border border-violet-500/30' : 'hover:bg-white/5 border border-transparent'}`}
                        onClick={() => {
                            if (onSelect) onSelect(item.id);
                        }}
                    >
                        {level === 0 ? <FolderOpen size={16} className={isSelected ? "text-violet-300" : "text-violet-400"} /> : <Folder size={14} className={isSelected ? "text-violet-300" : "text-slate-500"} />}
                        <span className={`text-sm font-fantasy tracking-wide flex-1 ${isSelected ? 'text-white' : 'text-slate-300'}`}>{item.name}</span>
                        {item.code && <span className="text-xs text-slate-600 font-mono mr-2">{item.code}</span>}

                        {!onSelect && (
                            <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                {onEdit && <button onClick={(e) => { e.stopPropagation(); onEdit(item); }} className="p-1 hover:text-violet-300 text-slate-500"><Edit2 size={12} /></button>}
                                {onDelete && <button onClick={(e) => { e.stopPropagation(); onDelete(item.id); }} className="p-1 hover:text-red-400 text-slate-500"><Trash2 size={12} /></button>}
                            </div>
                        )}
                    </div>
                    <AdminCategoryTree 
                        items={items} 
                        parentId={item.id} 
                        level={level + 1} 
                        onEdit={onEdit} 
                        onDelete={onDelete} 
                        onSelect={onSelect}
                        selectedId={selectedId}
                        excludeId={excludeId}
                    />
                </div>
            )})}
        </div>
    );
};

