export const LoreAdminContainer: React.FC = () => {
  const [adminTab, setAdminTab] = useState<'library_cats' | 'wiki_cats'>('library_cats');

  const { categories: libCats, addCategory: addLibCat, updateCategory: updateLibCat, deleteCategory: deleteLibCat } = useLibraryCategories(); 
  const { categories: wikiCats, addCategory: addWikiCat, updateCategory: updateWikiCat, deleteCategory: deleteWikiCat } = useLoreCategories();

  // Admin Form State
  const [isEditingCat, setIsEditingCat] = useState(false);
  const [catForm, setCatForm] = useState<{id?: string | number, name: string, parent_id: string | number | null, code?: string, description?: string}>({
      name: '', parent_id: null, code: '', description: ''
  });
  const [isParentSelectorOpen, setIsParentSelectorOpen] = useState(false);

  // Confirmation State
  const [confirmState, setConfirmState] = useState<{isOpen: boolean, title: string, message: string, onConfirm: () => void}>({
      isOpen: false, title: '', message: '', onConfirm: () => {}
  });

  const handleCatSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!catForm.name) return;

      if (adminTab === 'library_cats') {
          // Library Logic
          if (catForm.id) {
              await updateLibCat(Number(catForm.id), {
                  name: catForm.name,
                  parent_id: Number(catForm.parent_id) || null,
                  code: catForm.code
              });
          } else {
              await addLibCat(catForm.name, Number(catForm.parent_id) || null);
          }
      } else {
          // Wiki Logic
          if (catForm.id) {
              await updateWikiCat(String(catForm.id), { 
                  name: catForm.name, 
                  description: catForm.description, 
                  parent_id: catForm.parent_id ? String(catForm.parent_id) : null 
              });
          } else {
              await addWikiCat({ 
                  name: catForm.name, 
                  description: catForm.description, 
                  parent_id: catForm.parent_id ? String(catForm.parent_id) : null
              });
          }
      }
      setCatForm({ name: '', parent_id: null, code: '', description: '' });
      setIsEditingCat(false);
  };

  const handleEditClick = (item: any) => {
      setCatForm({
          id: item.id,
          name: item.name,
          parent_id: item.parent_id || null,
          code: item.code || '',
          description: item.description || ''
      });
      setIsEditingCat(true);
      setIsParentSelectorOpen(false);
  };

  const handleDeleteClick = (id: string | number) => {
      setConfirmState({
          isOpen: true,
          title: "Удалить Категорию",
          message: "Вы уверены? Это может привести к удалению вложенного содержимого.",
          onConfirm: async () => {
              if (adminTab === 'wiki_cats') {
                  await deleteWikiCat(String(id));
              } else {
                   await deleteLibCat(Number(id));
              }
          }
      });
  };

  const currentCats = adminTab === 'library_cats' ? libCats : wikiCats;
  const parentName = catForm.parent_id 
    ? currentCats.find(c => String(c.id) === String(catForm.parent_id))?.name 
    : '(Корень)';

  return (
      <div className="flex flex-col h-full bg-[#050b14] p-4">
          <div className="flex border-b border-slate-700 mb-4">
              <button 
                onClick={() => { setAdminTab('library_cats'); setCatForm({ name: '', parent_id: null }); setIsEditingCat(false); setIsParentSelectorOpen(false); }}
                className={`flex-1 py-2 text-sm font-fantasy tracking-wider ${adminTab === 'library_cats' ? 'text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-slate-300'}`}
              >
                  Категории Библиотеки
              </button>
              <button 
                onClick={() => { setAdminTab('wiki_cats'); setCatForm({ name: '', parent_id: null }); setIsEditingCat(false); setIsParentSelectorOpen(false); }}
                className={`flex-1 py-2 text-sm font-fantasy tracking-wider ${adminTab === 'wiki_cats' ? 'text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-slate-300'}`}
              >
                  Категории Вики
              </button>
          </div>

          <div className="flex-1 overflow-hidden flex flex-col md:flex-row gap-4">
              {/* Left: Tree View */}
              <div className="flex-1 overflow-y-auto custom-scrollbar border border-slate-800 rounded bg-slate-900/30 p-2">
                  <div className="text-xs text-slate-500 uppercase tracking-widest font-bold mb-2 pl-2">Структура</div>
                  <AdminCategoryTree 
                    items={currentCats} 
                    onEdit={handleEditClick} 
                    onDelete={handleDeleteClick} 
                  />
              </div>

              {/* Right: Form */}
              <div className="w-full md:w-1/3 bg-slate-900/50 p-4 rounded border border-slate-700 flex flex-col relative">
                  <h4 className="text-sm font-fantasy text-violet-300 mb-4 border-b border-slate-700 pb-2">
                      {isEditingCat ? "Ред. Категорию" : "Новая Категория"}
                  </h4>
                  <form onSubmit={handleCatSubmit} className="space-y-3 flex-1 flex flex-col">
                      <div>
                          <label className="text-xs text-slate-400 block mb-1">Название</label>
                          <MagicalInput 
                            required
                            value={catForm.name}
                            onChange={(e) => setCatForm({...catForm, name: e.target.value})}
                          />
                      </div>

                      {/* Improved Parent Selector */}
                      <div className="relative">
                          <label className="text-xs text-slate-400 block mb-1">Родитель</label>
                          <button 
                            type="button"
                            onClick={() => setIsParentSelectorOpen(!isParentSelectorOpen)}
                            className="w-full bg-[#020408] border border-violet-900/40 p-2.5 rounded-lg text-violet-100 flex items-center justify-between text-sm hover:border-violet-500 transition-colors"
                          >
                              <span className="truncate">{parentName}</span>
                              <ChevronDown size={14} className={`text-slate-500 transition-transform ${isParentSelectorOpen ? 'rotate-180' : ''}`} />
                          </button>

                          {isParentSelectorOpen && (
                              <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-[#050b14] border border-violet-500/30 rounded-lg shadow-xl max-h-60 overflow-y-auto custom-scrollbar p-2">
                                  <button 
                                    type="button" 
                                    className="w-full text-left p-2 hover:bg-white/5 text-sm text-slate-400 italic mb-1 border-b border-white/5"
                                    onClick={() => { setCatForm({...catForm, parent_id: null}); setIsParentSelectorOpen(false); }}
                                  >
                                      (Корень)
                                  </button>
                                  <AdminCategoryTree 
                                    items={currentCats} 
                                    onSelect={(id) => { setCatForm({...catForm, parent_id: id}); setIsParentSelectorOpen(false); }}
                                    selectedId={catForm.parent_id}
                                    excludeId={catForm.id ? catForm.id : undefined}
                                  />
                              </div>
                          )}
                      </div>

                      {adminTab === 'wiki_cats' && (
                          <div>
                              <label className="text-xs text-slate-400 block mb-1">Описание</label>
                              <textarea 
                                className="w-full bg-[#020408] border border-violet-900/40 p-2 text-sm rounded text-slate-300 focus:border-violet-500 outline-none resize-none"
                                rows={3}
                                value={catForm.description || ''}
                                onChange={(e) => setCatForm({...catForm, description: e.target.value})}
                              />
                          </div>
                      )}

                      <div className="mt-auto pt-4 flex gap-2">
                          {isEditingCat && (
                              <button 
                                type="button"
                                onClick={() => { setIsEditingCat(false); setCatForm({ name: '', parent_id: null, code: '', description: '' }); }}
                                className="flex-1 px-3 py-2 bg-slate-800 text-slate-400 text-xs rounded hover:bg-slate-700"
                              >
                                  Отмена
                              </button>
                          )}
                          <button 
                            type="submit" 
                            className="flex-1 px-3 py-2 bg-violet-700 text-white text-xs font-bold uppercase tracking-wider rounded hover:bg-violet-600 shadow-[0_0_10px_rgba(139,92,246,0.3)]"
                          >
                              {isEditingCat ? "Сохранить" : "Создать"}
                          </button>
                      </div>
                  </form>
              </div>
          </div>

          <ConfirmationModal 
            isOpen={confirmState.isOpen}
            title={confirmState.title}
            message={confirmState.message}
            onClose={() => setConfirmState(prev => ({ ...prev, isOpen: false }))}
            onConfirm={confirmState.onConfirm}
            isDangerous
          />
      </div>
  );
};

interface LoreModuleProps {
  isAdmin?: boolean;
}

