  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isDialectUnlocked } = useDialect();
  const { showAlert } = useUI();
  const [activeTab, setActiveTab] = useState<Faction>(Faction.LIGHT);
  const [npcVolume, setNpcVolume] = useState<string>(NPC_VOLUMES[0]);

  const filtered = characters.filter(c => {
    // Defensive check: ensure identity exists
    if (!c.identity) return false;

    // Check for Companion/Slave specific volume
    const isCompanion = c.identity.faction === Faction.NPC && c.identity.npc_volume === "Спутники и Рабы";

    // Hide "Units/Minions" from the main roster if they have a master_id,
    // UNLESS they are specifically "Companions/Slaves" from the Bestiary.
    if (c.meta.master_id && !isCompanion) return false;

    if (c.identity.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.identity.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          topGradient: "from-amber-500/10 via-amber-500/5 to-transparent",
          bottomGradient: "from-amber-500/10 via-amber-500/5 to-transparent",
          topLine: "bg-amber-400/30 shadow-[0_0_15px_rgba(251,191,36,0.3)]"
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          topGradient: "from-violet-900/20 via-violet-900/5 to-transparent",
          bottomGradient: "from-violet-900/20 via-violet-900/5 to-transparent",
          topLine: "bg-violet-500/30 shadow-[0_0_15px_rgba(139,92,246,0.3)]"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          topGradient: "from-red-900/15 via-red-900/5 to-transparent",
          bottomGradient: "from-red-900/15 via-red-900/5 to-transparent",
          topLine: "bg-red-500/30 shadow-[0_0_15px_rgba(239,68,68,0.3)]"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          topGradient: "from-slate-800/20 via-slate-800/5 to-transparent",
          bottomGradient: "from-slate-800/20 via-slate-800/5 to-transparent",
          topLine: "bg-slate-500/30 shadow-[0_0_15px_rgba(148,163,184,0.3)]"
        };
      default: 
        return { tab: "", topGradient: "", bottomGradient: "", topLine: "" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;

    // [DIALECT] Map faction enum to dictionary key
    const labelKey = faction === Faction.LIGHT ? 'fac_light' : 
                     faction === Faction.DARK ? 'fac_dark' :
                     faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

    return (
      <button
        onClick={() => setActiveTab(faction)}
        className={`relative flex items-center gap-2 px-4 md:px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? theme.tab : "text-slate-600 hover:text-slate-400"
        }`}
      >
        <Icon size={16} />
        {/* [DIALECT] */}
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-px ${theme.topLine.split(' ')[0]}`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className="hover:text-violet-400 transition-colors cursor-pointer select-none active:scale-90 inline-block"
      >
        {char}
      </span>
    ));
  };

  return (
    <div className="w-full relative px-4 md:px-6 pt-4 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
        {/* [DIALECT] Interactive Title for Easter Egg - Font Changed to Gothic */}
        <h1 className="text-2xl md:text-5xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r from-slate-200 via-violet-200 to-slate-200 tracking-[0.07em] uppercase flex items-center gap-3 drop-shadow-[0_0_15px_rgba(139,92,246,0.3)] opacity-90">
            {/* Inline SVG Logo to match favicon.svg exact structure */}
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" fill="none" className="w-6 h-6 md:w-10 md:h-10 opacity-80 drop-shadow-glow">
              <path d="M50 5 L93.3 30 V80 L50 105 L6.7 80 V30 L50 5 Z" fill="#0891b2" transform="translate(0 -5)"/>
              <text x="50" y="53" fontFamily="sans-serif" fontWeight="900" fontSize="50" fill="white" textAnchor="middle">C</text>
              <text x="50" y="87" fontFamily="sans-serif" fontWeight="900" fontSize="50" fill="white" textAnchor="middle">T</text>
            </svg>
            <div className="flex items-center gap-2">
              <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Трекер'))}</span> 
              <span 
                onClick={(e) => {
                   e.stopPropagation();
                   handleSlashClick();
                }}
                className="text-violet-700 cursor-pointer hover:text-violet-400 transition-colors select-none active:scale-90 inline-block drop-shadow-glow"
              >
                //
              </span> 
              <span className="flex">{renderInteractiveTitle(t('app_title_2', 'Персонажей'))}</span>
            </div>
        </h1>

        {/* Auth Panel */}
        {isAdmin && (
          <div className="flex items-center gap-3 bg-[#050b14] p-1.5 rounded-sm border border-violet-900/20 shadow-lg">
              <div className="flex items-center gap-2 px-3">
                 <ShieldCheck size={14} className="text-violet-500" />
                 <span className="text-[10px] font-bold text-violet-300 uppercase tracking-wider font-serif">Admin</span>
              </div>
              <Button onClick={onCreate} size="sm" className="shadow-glow bg-violet-900/50 border-violet-500/50 hover:bg-violet-800">
                {/* [DIALECT] */}
                <Plus size={14} /> {t('btn_new', 'New')}
              </Button>
          </div>
        )}
      </div>

      <div className="flex border-b border-violet-900/10 overflow-x-auto no-scrollbar z-20 relative">
        <TabButton faction={Faction.LIGHT} icon={Sun} />
        <TabButton faction={Faction.DARK} icon={Moon} />
        <TabButton faction={Faction.GRAVEYARD} icon={Skull} />
        <TabButton faction={Faction.NPC} icon={Ghost} />
      </div>

      {/* Main Content Area - Growing with content */}
      <div className="relative min-h-[500px]">

        {/* 1. Top Lamp: Attached to the separator line */}
        <div className={`absolute top-0 left-0 right-0 h-48 bg-gradient-to-b ${theme.topGradient} pointer-events-none z-0 transition-all duration-700`}></div>

        {/* 2. The Glowing Separator Line */}
        <div className={`absolute top-0 left-0 right-0 h-px w-full ${theme.topLine} z-10 transition-all duration-700`}></div>

        <div className="py-8 relative z-10">
          {activeTab === Faction.NPC && (
            <div className="mb-6 p-4 bg-[#050b14] border border-violet-900/30 relative z-10 rune-clip-r max-w-lg shadow-[0_0_20px_rgba(0,0,0,0.5)]">
              {/* [DIALECT] */}
              <label className="text-[10px] uppercase font-bold text-slate-500 mb-2 block tracking-widest font-serif">{t('lbl_npc_vol', "Архив Бестиария")}</label>
              <select 
                value={npcVolume} 
                onChange={(e) => setNpcVolume(e.target.value)}
                className="bg-[#020617] border border-slate-800 text-slate-300 text-sm rounded-sm w-full p-2 focus:border-violet-600 focus:shadow-glow outline-none font-serif tracking-wide"
              >
                {NPC_VOLUMES.map(v => <option key={v} value={v}>{getVolumeLabel(v)}</option>)}
              </select>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 relative z-10">
            {filtered.map(char => (
              <Card key={char.id} className="cursor-pointer hover:border-violet-500/40 transition-all hover:bg-[#0b0f19] bg-[#050b14] border-violet-900/20 group relative overflow-hidden shadow-lg hover:shadow-[0_0_15px_rgba(139,92,246,0.1)]" >
                <div onClick={() => onSelect(char.id)} className="h-full flex flex-col">
                  <div className="flex items-start gap-4 mb-4">

                    {/* Avatar with Level Badge */}
                    <div className="relative flex-shrink-0">
                      <div className="w-16 h-16 bg-[#020617] flex items-center justify-center border border-slate-800 overflow-hidden grayscale group-hover:grayscale-0 transition-all duration-500 rune-clip">
                        {char.meta.avatar_url ? <img src={char.meta.avatar_url} className="w-full h-full object-cover" /> : <UserIcon size={32} className="text-slate-700" />}
                      </div>
                      {/* Level Badge Top-Left */}
                      <div className="absolute -top-1 -left-1 w-5 h-5 bg-black border border-violet-900/50 flex items-center justify-center shadow-lg z-10">
                        <span className="text-[10px] font-bold text-violet-300 font-mono">{char.identity.level}</span>
                      </div>
                    </div>

                    <div className="flex-1 min-w-0">
                      <h3 className="font-bold font-serif text-lg text-slate-200 group-hover:text-violet-200 transition-colors truncate tracking-wide">{char.identity.name}</h3>

                      {/* Master Link Indicator */}
                      {char.meta.master_id && char.identity.faction === Faction.NPC && (
                        <div className="flex items-center gap-1 text-[10px] text-violet-400 mb-1 font-serif uppercase tracking-wider">
                            <LinkIcon size={10} /> 
                            {/* [DIALECT] */}
                            <span>{t('lbl_linked', 'Связан')}</span>
                        </div>
                      )}

                      {/* Save Status / Death Status */}
                      {char.identity.faction === Faction.GRAVEYARD ? (
                         <div className="flex items-center gap-1.5 mt-1">
                            <Skull size={12} className="text-slate-500" />
                            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500/80 truncate max-w-[150px]" title={char.meta.save_status_reason || "Причина смерти не указана"}>
                                {/* [DIALECT] */}
                                {char.meta.save_status_reason || t('meta_death_unknown', "Умер")}
                            </span>
                         </div>
                      ) : (
                          <div className="flex items-center gap-1.5 mt-1">
                            {char.meta.save_status ? (
                                <>
                                  <ShieldCheck size={12} className="text-emerald-500" />
                                  <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-500/80 font-serif">
                                      {/* [DIALECT] */}
                                      {t('meta_save_ok', 'Есть сейв')}
                                  </span>
                                </>
                            ) : (
                                <>
                                  <Skull size={12} className="text-red-500" />
                                  <span className="text-[10px] font-bold uppercase tracking-wider text-red-500/80 truncate max-w-[150px]" title={char.meta.save_status_reason || t('meta_save_lost', "Сейв потерян")}>
                                      {/* [DIALECT] */}
                                      {char.meta.save_status_reason || t('meta_save_lost', "Сейв потерян")}
                                  </span>
                                </>
                            )}
                          </div>
                      )}

                      {/* Stats Row with Icons */}
                      <div className="flex gap-2 mt-2 opacity-60 group-hover:opacity-100 transition-opacity">
                        <div className="flex items-center gap-1 text-[10px] text-red-400">
                          <Sword size={10} /> <span className="font-mono font-bold">{char.stats.phys}</span>
                        </div>
                        <div className="flex items-center gap-1 text-[10px] text-violet-400">
                          <Wand2 size={10} /> <span className="font-mono font-bold">{char.stats.magic}</span>
                        </div>
                        <div className="flex items-center gap-1 text-[10px] text-emerald-400">
                          <Crown size={10} /> <span className="font-mono font-bold">{char.stats.unique}</span>
                        </div>
                      </div>

                    </div>
                  </div>

                  {/* Equipment Preview */}
                  <div className="text-[10px] text-slate-500 truncate mt-auto pt-3 border-t border-violet-900/10 font-sans">
                    {/* [DIALECT] */}
                    {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || t('msg_no_eq', "Нет экипировки")}
                  </div>
                </div>
              </Card>
            ))}
            {filtered.length === 0 && (
              <div className="col-span-full flex flex-col items-center justify-center py-16 text-slate-700 border border-dashed border-slate-800 rounded-lg">
                <Ghost size={48} className="mb-4 opacity-20"/>
                {/* [DIALECT] */}
                <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Здесь никого нет')}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* [DIALECT] Easter Egg Input Window */}
      {isInputMode && !isDialectUnlocked && (
         <div className="fixed bottom-8 left-4 z-[100] animate-fade-in w-[calc(100%-2rem)] max-w-sm">
            <div className="bg-black/90 border border-violet-900 rounded-lg p-4 shadow-[0_0_20px_rgba(139,92,246,0.3)] backdrop-blur-sm rune-clip">
               <div className="flex items-center gap-2 mb-2">
                 <Terminal size={14} className="text-violet-500 animate-pulse"/>
                 <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
               </div>
               <div className="bg-slate-900/50 border border-slate-800 rounded p-3 h-12 flex items-center justify-center">
                  <span className="font-serif text-xl text-violet-400 tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)]">
                     {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                  </span>
               </div>
               <div className="text-center mt-2">
                  <span className="text-[9px] text-slate-600 uppercase">Click title letters to input</span>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

export default Roster;

import React, { useState, useEffect } from 'react';
import { INITIAL_CHARACTER, DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from './constants';
import { CharacterData, InjuryDefinition, TimeUnit } from './types';
import * as SupabaseService from './utils/supabaseService';
import Roster from './components/Roster';
import SheetHeader from './components/SheetHeader';
import TabEquipment from './components/TabEquipment';
import TabAbilities from './components/TabAbilities';
import TabPassives from './components/TabPassives';
import TabDebuffs from './components/TabDebuffs';
import TabUnits from './components/TabUnits';
import TabMedCard from './components/TabMedCard';
import GlobalSettingsModal from './components/GlobalSettingsModal';
import { Button } from './components/Shared';
import { Save, ChevronLeft, Edit3, Trash2, RotateCcw, Settings, BookOpen, Calculator, ScrollText, Loader2 } from 'lucide-react';
import { DialectProvider, useDialect } from './dialect_module/DialectContext';
import { UIProvider, useUI } from './context/UIContext';

export type DisplayMode = 'lore' | 'mech';

interface RosterModuleProps {
  isAdmin?: boolean;
}

const RosterContent: React.FC<RosterModuleProps> = ({ isAdmin = false }) => {
  const { toggleDialect, isOldSlavonic, isDialectUnlocked, t } = useDialect();
  const { showAlert, showConfirm } = useUI();

  // App State
  const [view, setView] = useState<'roster' | 'sheet'>('roster');
  const [characters, setCharacters] = useState<CharacterData[]>([]);
  const [isLoadingData, setIsLoadingData] = useState(true);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [charStack, setCharStack] = useState<string[]>([]);

  // Sheet State
  const [displayMode, setDisplayMode] = useState<DisplayMode>('lore');
  const [isEditMode, setIsEditMode] = useState(false);
  const [activeTab, setActiveTab] = useState<'equipment' | 'abilities' | 'passives' | 'debuffs' | 'units' | 'med_card'>('equipment');

  // Global Configs
  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);

  // Fetch Data
  useEffect(() => {
    const init = async () => {
      setIsLoadingData(true);
      try {
        const [chars, trigs, inj, units] = await Promise.all([
          SupabaseService.getAllCharacters(),
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setCharacters(chars);
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } catch (e) {
        console.error("Failed to init app", e);
      } finally {
        setIsLoadingData(false);
      }
    };
    init();
  }, []);

  const handleCreate = async () => {
    const newChar: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
    newChar.id = crypto.randomUUID();
    newChar.identity.name = "Новая Душа";

    // Optimistic UI
    setCharacters(prev => [...prev, newChar]);

    try {
      await SupabaseService.saveCharacter(newChar);
      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(true);
    } catch (e) {
      showAlert("Ошибка создания: " + e, "Сбой базы данных");
      setCharacters(prev => prev.filter(c => c.id !== newChar.id));
    }
  };

  const handleSelect = (id: string) => {
    setActiveCharId(id);
    setCharStack([id]);
    setView('sheet');
    setIsEditMode(false);
    window.scrollTo(0,0);
  };

  const handleNavigateToUnit = (unitId: string) => {
    setCharStack(prev => [...prev, unitId]);
    setActiveCharId(unitId);
    window.scrollTo(0,0);
  };

  const handleBack = () => {
    if (charStack.length > 1) {
      const newStack = [...charStack];
      newStack.pop();
      setCharStack(newStack);
      setActiveCharId(newStack[newStack.length - 1]);
    } else {
      setView('roster');
      setActiveCharId(null);
      setCharStack([]);
    }
  };

  const activeChar = characters.find(c => c.id === activeCharId);

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar);
      setIsEditMode(false);
    } catch (e) {
      showAlert("Ошибка сохранения: " + e, "Ошибка");
    }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
      await SupabaseService.saveCharacter(updated);
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;

    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          setCharacters(prev => prev.filter(c => c.id !== targetId));
          if (targetId === activeCharId) {
             handleBack();
          }
        } catch (e) {
          showAlert("Ошибка удаления: " + e, "Ошибка");
        }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.identity.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;

      try {
        await SupabaseService.saveCharacter(unit);
        setCharacters(prev => [...prev, unit]);
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) {
         showAlert("Cannot create unit: " + e, "Ошибка");
      }
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen text-slate-300 font-sans pb-20 selection:bg-violet-900/40 selection:text-white">

      {view === 'roster' && (
        <Roster 
          characters={characters} 
          onSelect={handleSelect} 
          onCreate={handleCreate} 
        />
      )}

      {view === 'sheet' && activeChar && (
        <div className="max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">

          {/* Top Navigation Bar */}
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button 
                  variant="secondary" 
                  size="sm" 
                  onClick={handleBack} 
                  className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide"
               >
                 <ChevronLeft size={18} /> 
                 {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && (
                 <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3">
                   {t('lbl_depth', 'Глубина')}: {charStack.length}
                 </span>
               )}
            </div>

            <div className="flex items-center gap-2">
               {isDialectUnlocked && (
                  <button 
                    onClick={toggleDialect} 
                    className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`}
                    title="Old Slavonic Dialect"
                  >
                     <ScrollText size={18} />
                  </button>
               )}

               <div className="h-6 w-px bg-slate-800 mx-1"></div>

               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button 
                    onClick={() => setDisplayMode('lore')}
                    className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    title="Lore Mode"
                  >
                    <BookOpen size={16} />
                  </button>
                  <button 
                    onClick={() => setDisplayMode('mech')}
                    className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    title="Mechanic Mode"
                  >
                    <Calculator size={16} />
                  </button>
               </div>

               {isAdmin && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>
                   {isEditMode ? (
                     <>
                        <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete">
                          <Trash2 size={16} />
                        </Button>
                        <Button variant="secondary" size="sm" onClick={() => {
                           showConfirm("Отменить несохраненные изменения?", () => setIsEditMode(false));
                        }}>
                           <RotateCcw size={16} />
                        </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}>
                          <Save size={16} /> {t('act_save', "Save")}
                        </Button>
                     </>
                   ) : (
                     <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}>
                       <Edit3 size={16} /> {t('act_edit', "Edit")}
                     </Button>
                   )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader 
            character={activeChar} 
            isEditMode={isEditMode} 
            onChange={updateActiveChar} 
            displayMode={displayMode}
            setDisplayMode={setDisplayMode}
            characters={characters}
            onNavigate={handleNavigateToUnit}
            onDelete={handleDelete}
            injuryDefinitions={injuryDefinitions}
          />

          {/* Sticky Navigation Tabs for Mobile */}
          <div className="sticky top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 md:mx-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {[
                  { id: 'equipment', label: t('tab_eq', 'Снаряжение') },
                  { id: 'abilities', label: t('tab_ab', 'Способности') },
                  { id: 'passives', label: t('tab_ps', 'Пассивки') },
                  { id: 'debuffs', label: t('tab_db', 'Дебаффы') },
                  { id: 'units', label: t('tab_un', 'Юниты') },
                  { id: 'med_card', label: t('tab_mc', 'Мед.Карта') },
                ].map(tab => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${
                        activeTab === tab.id 
                        ? 'text-violet-300' 
                        : 'text-slate-600 hover:text-slate-300'
                    }`}
                  >
                    {tab.label}
                    {activeTab === tab.id && (
                        <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div>
                    )}
                  </button>
                ))}
             </div>
          </div>

          {/* Full Width Content Area */}
          <div>
            {activeTab === 'equipment' && (
              <TabEquipment 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(eq) => updateActiveChar({ equipment: eq })} 
                displayMode={displayMode}
                onInstantUpdate={(eq) => handleInstantUpdate(eq)}
              />
            )}
            {activeTab === 'abilities' && (
              <TabAbilities 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(groups) => updateActiveChar({ ability_groups: groups })}
                displayMode={displayMode}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'passives' && (
              <TabPassives 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(p) => updateActiveChar({ passives: p })}
                displayMode={displayMode}
                triggersMap={triggersMap}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'debuffs' && (
              <TabDebuffs 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(p) => updateActiveChar({ passives: p })}
                displayMode={displayMode}
                triggersMap={triggersMap}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'units' && (
              <TabUnits 
                master={activeChar} 
                units={characters} 
                onCreateUnit={createUnit}
                onNavigateToUnit={handleNavigateToUnit}
                isEditMode={isEditMode}
              />
            )}
            {activeTab === 'med_card' && (
              <TabMedCard 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(mc) => updateActiveChar({ med_card: mc })}
                injuryDefinitions={injuryDefinitions}
              />
            )}
          </div>

        </div>
      )}
    </div>
  );
};

export const RosterAdminContainer: React.FC = () => {
  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const init = async () => {
      try {
        const [trigs, inj, units] = await Promise.all([
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } finally {
        setLoaded(true);
      }
    };
    init();
  }, []);

  if (!loaded) return <div className="p-8 text-violet-500 animate-pulse">Загрузка протоколов...</div>;

  return (
    <UIProvider>
      <div className="relative w-full h-full bg-[#0b0d12] flex flex-col">
         <GlobalSettingsModal 
            onClose={() => {}}
            triggersMap={triggersMap}
            onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }}
            injuryDefinitions={injuryDefinitions}
            onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }}
            timeUnits={timeUnits}
            onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }}
         />
      </div>
    </UIProvider>
  );
};

