                <span>v1.2</span>
                {isAdmin && <span className="text-emerald-500 font-bold">ADMIN</span>}
            </div>
        </div>
      </nav>

      {/* Main Content Area - Absolute positioning to fill remaining space */}
      <main className={`
          absolute inset-0 
          transition-all duration-500 
