// Helper to generate IDs for items inside JSON that might lack them
const generateId = () => Math.random().toString(36).substr(2, 9);

const getTags = (obj: any): string[] => {
    if (!obj) return [];
    let collected: string[] = [];
    if (Array.isArray(obj.tags)) {
        collected = [...obj.tags];
    } else if (typeof obj.tags === 'string') {
        collected.push(obj.tags);
    }
    if (typeof obj.tag === 'string') {
        collected.push(obj.tag);
    }
    return collected.map(t => t.toLowerCase().trim()).filter(Boolean);
};

export const calculateTraumaPenalty = (injuries: JsonInjury[] = []) => {
  let totals = { phys: 0, mag: 0, uniq: 0, total: 0 };
  const injuryCounts: Record<string, number> = {};

  injuries.forEach(injury => {
      const current = injuryCounts[injury.template_id] || 0;
      injuryCounts[injury.template_id] = current + (injury.count || 1);
  });

  for (const [templateId, count] of Object.entries(injuryCounts)) {
      const def = TRAUMA_DEFINITIONS[templateId];
      if (!def) continue;
      let penalty = 0;
      if (def.stack && def.stack > 0) {
          const stacks = Math.floor(count / def.stack);
          penalty = stacks * def.value;
      } else {
          penalty = count * def.value;
      }
      totals.total += penalty;
      if (templateId.includes('phys')) totals.phys += penalty;
      else if (templateId.includes('mag')) totals.mag += penalty;
      else if (templateId.includes('uniq')) totals.uniq += penalty;
  }
  return totals;
};

export async function getCharacters() {
  console.log('Fetching characters...');
  const { data, error } = await supabase.from('characters').select('*');
  if (error) { console.error('Supabase: Error fetching characters:', error); return { data: [], error }; }
  if (!data) return { data: [], error: null };

  const formattedData = data.map((row: any) => {
    let charData = row.data || row;
    if (row.id && !charData.id) charData.id = row.id;

    // --- STRUCTURAL ADAPTER ---
    // Handle 'identity' vs 'profile'
    if (charData.identity && !charData.profile) {
        charData.profile = { 
            ...charData.identity,
            currencies: charData.meta?.currencies || { juhe: 0, jumi: 0 }
        };
    }
    // Handle 'med_card' vs 'medcard'
    if (charData.med_card && !charData.medcard) {
        charData.medcard = charData.med_card;
    }

    if (!charData.equipment) charData.equipment = { usable: [], wearable: [], inventory: [] };
    if (!charData.ability_groups) charData.ability_groups = [];
    if (!charData.passives) charData.passives = [];
    if (!charData.stats) charData.stats = { phys: 0, magic: 0, unique: 0 };

    if (!charData.profile) charData.profile = { name: 'Unknown', level: 1, faction: 'None', npc_volume: '' };
    if (!charData.meta) charData.meta = { uid: 'system', avatar_url: '' };

    if (!charData.medcard) charData.medcard = { injuries: [], conditions: [] };
    if (!charData.medcard.injuries) charData.medcard.injuries = [];

    // --- 2. EQUIPMENT PROCESSING ---
    charData.equipment.usable = (charData.equipment.usable || []).map((item: JsonItem) => ({
        ...item, _id: generateId(), tags: getTags(item), bonuses: item.bonuses || []
    }));
    charData.equipment.wearable = (charData.equipment.wearable || []).map((item: JsonItem) => ({
        ...item, _id: generateId(), tags: getTags(item), bonuses: item.bonuses || [], is_equipped: item.is_equipped || false
    }));

    // --- 3. FLATTENING ---
    const flatAbilities: JsonAbility[] = [];
    const flatPassives: JsonPassiveItem[] = [];

    if (charData.ability_groups) {
        charData.ability_groups = charData.ability_groups.map((group: any) => {
            const groupTags = getTags(group);
            const abilities = Array.isArray(group.abilities) ? group.abilities.map((ab: JsonAbility) => {
                const itemTags = getTags(ab);
                const mergedTags = [...new Set([...groupTags, ...itemTags])];
                const hydratedAbility = { ...ab, _id: generateId(), tags: mergedTags, bonuses: ab.bonuses || [], limit: ab.limit, limit_unit: ab.limit_unit };
                if (!mergedTags.includes('no_war')) flatAbilities.push(hydratedAbility);
                return hydratedAbility;
            }) : [];
            return { ...group, abilities };
        });
    }

    if (charData.passives) {
        charData.passives = charData.passives.map((group: any) => {
            const groupTags = getTags(group);
            const items = Array.isArray(group.items) ? group.items.map((p: JsonPassiveItem) => {
                const itemTags = getTags(p);
                const mergedTags = [...new Set([...groupTags, ...itemTags])];
                const hydratedPassive = { ...p, _id: generateId(), tags: mergedTags, bonuses: p.bonuses || [] };
                flatPassives.push(hydratedPassive);
                return hydratedPassive;
            }) : [];
            return { ...group, items };
        });
    }

    // --- 4. BATTLE STATS ---
    const trauma = calculateTraumaPenalty(charData.medcard.injuries);
    charData.battle_stats = {
        hp_penalty_current: trauma.total,
        trauma_phys: trauma.phys,
        trauma_mag: trauma.mag,
        trauma_uniq: trauma.uniq,
        actions_max: 4, actions_left: 4
    };

    charData.flat_abilities = flatAbilities;
    charData.flat_passives = flatPassives;

    return charData;
  });

  return { data: formattedData as CharacterTemplate[], error: null };
}

export async function getBattles() {
  const { data, error } = await supabase.from('battles').select('*');
  if (error) console.error('Supabase: Error fetching battles:', error);
  return { data, error };
}

export async function createBattle(name: string) {
  const { data, error } = await supabase.from('battles').insert([{ name, participants_snapshot: [], sequence_log: [], casualties: [], round: 1, status: 'startup' }]).select().single();
  if (error) console.error('Supabase: Error creating battle:', error);
  return { data, error };
}

export async function updateBattle(battleId: string, updates: any) {
  const { data, error } = await supabase.from('battles').update(updates).eq('id', battleId);
  if (error) console.error('Supabase: Error updating battle:', error);
  return { data, error };
}

export async function deleteBattle(battleId: string) {
    const { error } = await supabase.from('battles').delete().eq('id', battleId);
    if (error) console.error('Supabase: Error deleting battle:', error);
    return { error };
}

