import React, { useState, useEffect } from 'react';
import { BattleParticipant, SequenceStep, TargetConfig, ReactionType, SequenceNode, JsonAbility } from '../types';
import { calculateSequenceTree } from '../engine/calculator';
import { MOCK_ABILITIES } from '../constants';

interface Props {
  participants: BattleParticipant[];
  draft: SequenceStep;
  setDraft: React.Dispatch<React.SetStateAction<SequenceStep>>;
  onCommit: (formattedString: string, cost: number) => void;
}

const SequenceBuilder: React.FC<Props> = ({ participants, draft, setDraft, onCommit }) => {
  const actor = participants.find(p => p.instance_id === draft.actor_id);
  const [calculatedPreview, setCalculatedPreview] = useState<string>('');

  const availableAbilities: JsonAbility[] = actor ? [...actor.flat_abilities, ...MOCK_ABILITIES] : MOCK_ABILITIES;
  const uniqueAbilities: JsonAbility[] = Array.from(new Map(availableAbilities.map(item => [item._id, item])).values());

  useEffect(() => {
    if (draft.actor_id && draft.ability_ids.length > 0) {
      const nodes: SequenceNode[] = [{
          id: 'temp-combo',
          type: 'combo',
          children: draft.ability_ids.map(aid => ({
              id: `temp-${aid}`,
              type: 'action',
              data: { charId: draft.actor_id, abilityId: aid },
              children: []
          }))
      }];

      const result = calculateSequenceTree(nodes, participants);
      setCalculatedPreview(result.formattedString);

    } else {
      setCalculatedPreview('Waiting for sequence...');
    }
  }, [draft, participants]);

  const toggleAbility = (id: string) => {
    setDraft(prev => {
      const exists = prev.ability_ids.includes(id);
      return {
        ...prev,
        ability_ids: exists 
          ? prev.ability_ids.filter(aid => aid !== id)
          : [...prev.ability_ids, id]
      };
    });
  };

  const updateTargetReaction = (participantId: string, reaction: ReactionType) => {
     setDraft(prev => {
        const targetIndex = prev.target_configs.findIndex(t => t.participant_id === participantId);
        if (targetIndex === -1) {
            return {
                ...prev,
                target_configs: [...prev.target_configs, { participant_id: participantId, reaction }]
            };
        }
        const newTargets = [...prev.target_configs];
        newTargets[targetIndex] = { ...newTargets[targetIndex], reaction };
        return { ...prev, target_configs: newTargets };
     });
  };

  const removeTarget = (participantId: string) => {
      setDraft(prev => ({
          ...prev,
          target_configs: prev.target_configs.filter(t => t.participant_id !== participantId)
      }));
  };

  if (!actor) {
    return (
      <div className="h-full flex items-center justify-center text-slate-500 border-2 border-dashed border-console-700 rounded-lg">
        Select an Actor from the left column to begin.
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-console-800 rounded-lg p-4 shadow-xl border border-console-700">

      {/* Header: Actor Info */}
      <div className="flex items-center gap-4 border-b border-console-700 pb-4 mb-4">
        <div className="w-12 h-12 rounded bg-yellow-600/20 text-yellow-500 flex items-center justify-center border border-yellow-600/50 font-bold">
            {actor.profile.name.substring(0, 2)}
        </div>
        <div>
            <h2 className="text-lg font-bold text-white">Sequence Builder</h2>
            <p className="text-sm text-slate-400">Actor: <span className="text-yellow-400">{actor.profile.name}</span></p>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 space-y-6">

        {/* Section 1: Abilities (Combo) */}
        <div>
            <h3 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">Select Abilities (Combo)</h3>
            <div className="grid grid-cols-2 gap-2">
                {uniqueAbilities.map(ability => {
                    const isSelected = draft.ability_ids.includes(ability._id);
                    const order = draft.ability_ids.indexOf(ability._id) + 1;

                    const totalBonus = ability.bonuses.reduce((acc, b) => acc + b.val, 0);

                    return (
                        <button
                            key={ability._id}
                            onClick={() => toggleAbility(ability._id)}
                            className={`
                                relative flex items-center justify-between px-3 py-2 rounded border text-sm text-left transition-all
                                ${isSelected 
                                    ? 'bg-blue-900/30 border-blue-500 text-blue-100 shadow-[0_0_10px_rgba(59,130,246,0.2)]' 
                                    : 'bg-console-900 border-console-700 text-slate-400 hover:border-slate-500'}
                            `}
                        >
                            <div className="flex flex-col">
                                <span className="font-semibold">{ability.name}</span>
                                <span className="text-[10px] opacity-70">Bonus: {totalBonus}</span>
                            </div>
                            {isSelected && (
                                <span className="flex items-center justify-center w-5 h-5 rounded-full bg-blue-500 text-white text-xs font-bold">
                                    {order}
                                </span>
                            )}
                        </button>
                    );
                })}
            </div>
        </div>

        {/* Section 2: Targets & Reactions */}
        <div>
             <h3 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">Targets & Reactions</h3>
             {draft.target_configs.length === 0 ? (
                 <div className="p-3 bg-console-900/50 border border-dashed border-console-700 rounded text-center text-sm text-slate-500">
                     Select targets from the left column
                 </div>
             ) : (
                 <div className="space-y-2">
                     {draft.target_configs.map(tConfig => {
                         const targetParticipant = participants.find(p => p.instance_id === tConfig.participant_id);
                         if (!targetParticipant) return null;

                         return (
                             <div key={tConfig.participant_id} className="flex items-center gap-3 bg-console-900 border border-console-600 p-2 rounded">
                                 <div className="w-6 h-6 rounded bg-slate-700 flex items-center justify-center text-[10px] text-white">
                                     {targetParticipant.profile.name.substring(0,2)}
                                 </div>
                                 <span className="text-sm font-medium text-slate-200 flex-1">{targetParticipant.profile.name}</span>

                                 <select 
                                    value={tConfig.reaction}
                                    onChange={(e) => updateTargetReaction(tConfig.participant_id, e.target.value as ReactionType)}
                                    className="bg-console-800 border border-console-600 text-xs text-white rounded px-2 py-1 outline-none focus:border-blue-500"
                                 >
                                     <option value="none">No Reaction</option>
                                     <option value="dodge">Dodge</option>
                                     <option value="block">Block</option>
                                 </select>

                                 <button 
                                    onClick={() => removeTarget(tConfig.participant_id)}
                                    className="text-slate-500 hover:text-red-400 px-2"
                                 >
                                     &times;
                                 </button>
                             </div>
                         );
                     })}
                 </div>
             )}
        </div>

        {/* Section 3: Conditionals (Visual Mock) */}
        <div>
            <div className="flex items-center justify-between mb-2">
                 <h3 className="text-xs font-bold uppercase text-slate-500 tracking-wider">Logic & Conditions</h3>
                 <button className="text-[10px] text-blue-400 hover:text-blue-300 hover:underline">+ Add Condition</button>
            </div>
            <div className="border-l-2 border-console-600 pl-3 ml-1 py-1">
                <div className="text-xs text-slate-500 italic mb-1">If (Armor Penetrated)...</div>
                <div className="p-2 border border-dashed border-console-700 rounded bg-console-900/30 text-xs text-slate-600 text-center">
                    Drag actions here (Not implemented in demo)
                </div>
            </div>
        </div>

      </div>

      {/* Footer: Preview & Commit */}
      <div className="mt-4 pt-4 border-t border-console-700">
          <div className="mb-3">
              <span className="text-[10px] uppercase text-slate-500 font-bold">Sequence Preview</span>
              <div className="mt-1 p-3 bg-black/40 border border-console-600 rounded font-mono text-sm text-green-400 break-words">
                  {calculatedPreview}
              </div>
          </div>

          <button 
            disabled={draft.ability_ids.length === 0}
            onClick={() => onCommit(calculatedPreview, 0)}
            className={`
                w-full py-3 rounded font-bold uppercase tracking-widest text-sm transition-all
                ${draft.ability_ids.length === 0
                    ? 'bg-console-700 text-slate-500 cursor-not-allowed'
                    : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg hover:shadow-blue-500/20'
                }
            `}
          >
              Commit Sequence
          </button>
      </div>
    </div>
  );
};

export default SequenceBuilder;

import React, { useState } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { SortableContext, horizontalListSortingStrategy, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { SequenceNode, BattleParticipant, JsonAbility } from '../types';
import { Trash2, GripVertical, Plus, Split, Zap, Box, Minus, Settings, Sword, CheckSquare, Square } from 'lucide-react';
import { getMatchingFactors } from '../engine/calculator';

interface CanvasNodeProps {
  node: SequenceNode;
  participants: BattleParticipant[];
  onRemove: (id: string) => void;
  onUpdateData: (id: string, data: any) => void;
  isInsideHorizontalContainer?: boolean;
  index?: number;
  onAddBranch?: (nodeId: string) => void;
}

const Tooltip: React.FC<{ title: string; desc?: string; mech?: string; tags?: string[] }> = ({ title, desc, mech, tags }) => (
    <div className="absolute left-0 bottom-full mb-2 w-64 bg-[#050b14]/95 text-white text-[10px] p-2 rounded shadow-glow border border-violet-900/50 opacity-0 group-hover/mod:opacity-100 transition-opacity pointer-events-none z-[9999] backdrop-blur-sm">
        <div className="font-bold mb-1 border-b border-violet-900 pb-1 text-yellow-500 font-rune tracking-wide">{title}</div>
        {mech && <div className="mb-1 text-cyan-300 font-mono text-xs">{mech}</div>}
        {desc && <div className="italic text-slate-400 mb-1 leading-tight font-serif">{desc}</div>}
        {tags && tags.length > 0 && (
            <div className="mt-1 text-xs text-slate-500 border-t border-gray-800 pt-1 font-mono uppercase">
                {tags.join(', ')}
            </div>
        )}
    </div>
);

const getAbilityCardStyles = (ability: JsonAbility) => {
    const tags = (ability.tags || []).map(t => t.toLowerCase());
    const stats = new Set<string>();

    if (tags.some(t => t.includes('phys') || t.includes('физ') || t === 'melee' || t === 'ranged')) stats.add('phys');
    if (tags.some(t => t.includes('magic') || t.includes('mag') || t.includes('маг') || t === 'spell')) stats.add('mag');
    if (tags.some(t => t.includes('unique') || t.includes('uniq') || t.includes('уник'))) stats.add('uniq');

    (ability.bonuses || []).forEach(b => {
        if (b.stat === 'phys') stats.add('phys');
        if (b.stat === 'magic') stats.add('mag');
        if (b.stat === 'unique') stats.add('uniq');
    });

    let baseClass = 'bg-panel border-slate-700/50';

    if (tags.some(t => t === 'form' || t === 'форма')) {
        baseClass = 'bg-yellow-900/20 border-yellow-600/40 text-yellow-100';
    } else if (tags.some(t => t === 'buff' || t === 'бафф')) {
        baseClass = 'bg-emerald-900/20 border-emerald-600/40 text-emerald-100';
    } else {
        const hasPhys = stats.has('phys');
        const hasMag = stats.has('mag');
        const hasUniq = stats.has('uniq');

        if (hasPhys && hasMag && hasUniq) {
            baseClass = 'bg-[linear-gradient(135deg,rgba(127,29,29,0.3)_0%,rgba(30,58,138,0.3)_50%,rgba(88,28,135,0.3)_100%)] border-slate-500/40 text-white';
        } else if (hasPhys && hasMag) {
            baseClass = 'bg-gradient-to-br from-red-900/30 to-blue-900/30 border-purple-500/30 text-white';
        } else if (hasPhys && hasUniq) {
            baseClass = 'bg-gradient-to-br from-red-900/30 to-purple-900/30 border-pink-500/30 text-white';
        } else if (hasMag && hasUniq) {
            baseClass = 'bg-gradient-to-br from-blue-900/30 to-purple-900/30 border-indigo-500/30 text-white';
        } else if (hasPhys) {
            baseClass = 'bg-red-950/30 border-red-800/30 text-red-100';
        } else if (hasMag) {
            baseClass = 'bg-blue-950/30 border-blue-800/30 text-blue-100';
        } else if (hasUniq) {
            baseClass = 'bg-purple-950/30 border-purple-800/30 text-purple-100';
        }
    }

    const isDebuff = ability.bonuses.some(b => b.val < 0);
    if (isDebuff && !tags.some(t => t === 'form' || t === 'форма')) {
         baseClass = 'bg-rose-950/30 border-rose-800/40 text-rose-100';
    }

    return baseClass;
};


const CanvasNode: React.FC<CanvasNodeProps> = ({ node, participants, onRemove, onUpdateData, isInsideHorizontalContainer, index, onAddBranch }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: node.id,
    data: { type: 'NODE', node }
  });

  const [showSettings, setShowSettings] = useState(false);
  const isComboFull = node.type === 'combo' && node.children.length >= 2;

  const { setNodeRef: setDroppableRef, isOver: isDroppableOver } = useDroppable({
    id: `container-${node.id}`,
    data: { type: 'CONTAINER', nodeId: node.id, nodeType: node.type },
    disabled: node.type === 'action' || node.type === 'divider' || isComboFull
  });

  const style = {
    transform: CSS.Translate.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1,
    zIndex: isDragging ? 999 : 1,
  };

  if (node.type === 'logic_chain') {
      return (
          <div ref={setNodeRef} style={style} className="shrink-0 w-full mb-3">
              <div className={`
                    bg-panel border border-amber-700/50 rounded-lg overflow-hidden shadow-lg flex flex-col transition-all
                    ${isDroppableOver ? 'ring-2 ring-amber-500 shadow-glow-gold' : ''}
                 `}
              >
                  <div className="bg-amber-900/20 p-2 border-b border-amber-800/50 flex items-center justify-between shrink-0">
                     <div className="flex items-center gap-2 text-amber-500 font-bold text-xs uppercase font-rune tracking-wider">
                         <div {...attributes} {...listeners} className="cursor-grab hover:text-white">
                            <Split size={14} />
                         </div>
                         Логический Блок
                     </div>
                     <button onClick={() => onRemove(node.id)} className="text-slate-600 hover:text-red-400"><Trash2 size={12} /></button>
                  </div>

                  <div ref={setDroppableRef} className="flex flex-col gap-1 p-2">
                       <SortableContext items={node.children.map(c => c.id)} strategy={verticalListSortingStrategy}>
                            {node.children.map((child, idx) => (
                                <CanvasNode 
                                    key={child.id} node={child} participants={participants} onRemove={onRemove} onUpdateData={onUpdateData}
                                    index={idx}
                                />
                            ))}
                       </SortableContext>
                  </div>

                  <div className="p-2 border-t border-amber-800/30 bg-amber-900/10 text-center">
                     {onAddBranch && (
                         <button onClick={() => onAddBranch(node.children[node.children.length - 1]?.id || node.id)} className="text-[10px] bg-amber-900/30 text-amber-400 px-3 py-1 rounded hover:bg-amber-800/50 border border-amber-800/40 uppercase font-bold tracking-wider w-full font-rune">
                            + Добавить Ветвь
                         </button>
                     )}
                  </div>
              </div>
          </div>
      );
  }

  if (node.type === 'divider') {
      return (
          <div ref={setNodeRef} style={style} className="w-full py-2 flex items-center justify-center group relative mb-2">
              <div {...attributes} {...listeners} className="absolute left-0 top-1/2 -translate-y-1/2 p-2 cursor-grab text-slate-600 hover:text-white z-10">
                 <GripVertical size={14} />
              </div>
              <div className="w-full h-[1px] bg-gradient-to-r from-transparent via-violet-900/50 to-transparent group-hover:via-violet-500 transition-all"></div>
              <div className="absolute bg-[#050b14] px-2 text-[10px] uppercase font-bold text-slate-600 border border-slate-800 rounded group-hover:border-violet-500 group-hover:text-violet-400 z-10 font-rune transition-colors">
                  Разделитель
              </div>
              <button onClick={() => onRemove(node.id)} className="absolute right-0 top-1/2 -translate-y-1/2 p-2 text-slate-600 hover:text-red-400 z-10">
                  <Trash2 size={12} />
              </button>
          </div>
      );
  }

  if (node.type === 'condition') {
      return (
        <div ref={setNodeRef} style={style} className="flex items-start gap-2 mb-2 w-full">
            <div className={`flex-1 border border-violet-900/40 rounded bg-slate-900/50 p-2 flex flex-col gap-2 transition-all ${isDroppableOver ? 'bg-violet-900/20 ring-1 ring-violet-500' : ''}`}>
                 <div className="flex items-center gap-2 mb-1">
                      <div {...attributes} {...listeners} className="cursor-grab text-slate-500 hover:text-white"><GripVertical size={14} /></div>
                      <input 
                        className="bg-transparent border-b border-slate-700 text-xs text-white w-full outline-none focus:border-violet-500 placeholder-slate-600 font-mono"
                        placeholder="Условие (напр. Если увернулся)..."
                        value={node.data?.conditionText || ''}
                        onChange={(e) => onUpdateData(node.id, { conditionText: e.target.value })}
                      />
                 </div>

                 <div ref={setDroppableRef} className="min-h-[40px] border border-dashed border-slate-800 rounded p-1 bg-black/20">
                     {node.children.length === 0 && <div className="text-[10px] text-slate-600 text-center py-2">Перетащите действие сюда</div>}
                     <SortableContext items={node.children.map(c => c.id)} strategy={verticalListSortingStrategy}>
                        {node.children.map((child, idx) => (
                            <CanvasNode key={child.id} node={child} participants={participants} onRemove={onRemove} onUpdateData={onUpdateData} index={idx} />
                        ))}
                     </SortableContext>
                 </div>
            </div>
            <button onClick={() => onRemove(node.id)} className="mt-2 text-slate-600 hover:text-red-400"><Trash2 size={14} /></button>
        </div>
      );
  }

  if (node.type === 'combo') {
      return (
        <div ref={setNodeRef} style={style} className="mb-3 w-full">
            <div className={`border border-blue-900/30 rounded-lg p-2 bg-gradient-to-r from-blue-950/20 to-transparent transition-all ${isDroppableOver ? 'ring-1 ring-blue-500 bg-blue-900/20' : ''}`}>
                <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                        <div {...attributes} {...listeners} className="cursor-grab text-slate-500 hover:text-blue-400"><GripVertical size={14} /></div>
                        <span className="text-[10px] uppercase font-bold text-blue-400 tracking-wider font-rune">Комбо-связка</span>
                    </div>
                    <button onClick={() => onRemove(node.id)} className="text-slate-600 hover:text-red-400"><Trash2 size={12} /></button>
                </div>

                <div ref={setDroppableRef} className="flex gap-2 min-h-[50px] items-center overflow-x-auto pb-1">
                    {node.children.length === 0 && <div className="text-[10px] text-slate-600 italic w-full text-center">Перетащите до 2 действий</div>}
                    <SortableContext items={node.children.map(c => c.id)} strategy={horizontalListSortingStrategy}>
                        {node.children.map((child, idx) => (
                            <div key={child.id} className="flex-1 min-w-[150px]">
                                <CanvasNode node={child} participants={participants} onRemove={onRemove} onUpdateData={onUpdateData} isInsideHorizontalContainer index={idx} />
                            </div>
                        ))}
                    </SortableContext>
                </div>
            </div>
        </div>
      );
  }

  if (node.type === 'action') {
      const charId = node.data?.charId;
      const abilityId = node.data?.abilityId;
      const actor = participants.find(p => p.instance_id === charId);

      let ability = actor?.flat_abilities?.find(a => a._id === abilityId);
      if (!ability && actor?.ability_groups) {
          actor.ability_groups.forEach(g => {
             const found = g.abilities.find(a => a._id === abilityId);
             if(found) ability = found;
          });
      }

      if (!ability || !actor) {
           return <div ref={setNodeRef} style={style} className="p-2 bg-red-900/20 border border-red-500/50 text-red-300 rounded text-xs">Unknown Action <button onClick={()=>onRemove(node.id)}>x</button></div>;
      }

      const cardStyle = getAbilityCardStyles(ability);
      const matchingFactors = getMatchingFactors(actor, ability.tags);
      const excluded = node.data?.excludedModifiers || [];

      const toggleModifier = (modName: string) => {
          const newExcluded = excluded.includes(modName) 
            ? excluded.filter(m => m !== modName)
            : [...excluded, modName];
          onUpdateData(node.id, { excludedModifiers: newExcluded });
      };

      return (
          <div ref={setNodeRef} style={style} className={`relative group p-2 rounded border shadow-sm transition-all ${cardStyle} ${isInsideHorizontalContainer ? 'h-full flex flex-col justify-between' : 'mb-2'}`}>
              <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2">
                       <div {...attributes} {...listeners} className="cursor-grab opacity-50 hover:opacity-100"><GripVertical size={12} /></div>
                       <div>
                           <div className="font-bold text-xs leading-tight">{ability.name}</div>
                           {/* Use profile.name */}
                           <div className="text-[9px] opacity-70">{actor.profile.name}</div>
                       </div>
                  </div>

                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => setShowSettings(!showSettings)} 
                        className={`p-0.5 rounded hover:bg-white/10 ${showSettings ? 'text-white' : 'text-slate-400'}`}
                      >
                         <Settings size={12} />
                      </button>
                      <button 
                        onClick={() => onRemove(node.id)} 
                        className="text-red-400 hover:bg-white/10 rounded p-0.5"
                      >
                        <Trash2 size={12} />
                      </button>
                  </div>
              </div>

              <div className="mt-2 text-[9px] flex flex-wrap gap-1">
                  {ability.tags.slice(0, 3).map(t => <span key={t} className="px-1 bg-black/20 rounded border border-white/10">{t}</span>)}
              </div>

              {showSettings && (
                  <div className="mt-2 pt-2 border-t border-white/10 text-[10px] space-y-2 animate-in slide-in-from-top-1 bg-black/20 -mx-2 px-2 pb-1 rounded-b">
                      {actor.equipment.usable.length > 0 && (
                        <div className="flex items-center gap-2">
                            <Sword size={10} className="text-slate-500 shrink-0" />
                            <select 
                                value={node.data?.weaponId || ''} 
                                onChange={(e) => onUpdateData(node.id, { weaponId: e.target.value })}
                                className="bg-black/30 border border-white/10 rounded px-1 py-0.5 w-full outline-none text-[9px] text-slate-300"
                                onClick={(e) => e.stopPropagation()} 
                                onPointerDown={(e) => e.stopPropagation()}
                            >
                                <option value="">Без оружия</option>
                                {actor.equipment.usable.map(w => <option key={w._id} value={w._id}>{w.name}</option>)}
                            </select>
                        </div>
                      )}

                      {matchingFactors.length > 0 ? (
                          <div className="space-y-1">
                              <div className="font-bold text-slate-500 uppercase tracking-wider text-[8px] mb-1">Модификаторы</div>
                              {matchingFactors.map(f => {
                                  const isActive = !excluded.includes(f.name);
                                  return (
                                      <button 
                                        key={f.name}
                                        onClick={(e) => { e.stopPropagation(); toggleModifier(f.name); }}
                                        className={`w-full flex items-center justify-between px-1.5 py-1 rounded border transition-all ${isActive ? 'bg-emerald-900/20 border-emerald-500/30 text-emerald-200' : 'bg-black/20 border-transparent text-slate-600'}`}
                                        onPointerDown={(e) => e.stopPropagation()}
                                      >
                                          <div className="flex items-center gap-1 overflow-hidden">
                                              {isActive ? <CheckSquare size={10} /> : <Square size={10} />}
                                              <span className={`truncate text-[9px] ${!isActive && 'line-through opacity-70'}`}>{f.name}</span>
                                          </div>
                                          <span className="font-mono text-[9px]">{f.bonus > 0 ? `+${f.bonus}` : f.bonus}</span>
                                          <Tooltip title={f.name} desc={f.desc} mech={f.mech} tags={f.tags} />
                                      </button>
                                  )
                              })}
                          </div>
                      ) : (
                          <div className="text-[8px] text-slate-600 italic text-center">Нет доступных модификаторов</div>
                      )}
                  </div>
              )}

              <Tooltip title={ability.name} desc={ability.desc_lore} mech={ability.desc_mech} tags={ability.tags} />
          </div>
      );
  }

  return null;
};

interface Props {
  tree: SequenceNode[];
  participants: BattleParticipant[];
  onRemove: (id: string) => void;
  onUpdateData: (id: string, data: any) => void;
  onAddCombo: () => void;
  onAddCondition: () => void;
  onAddDivider: () => void;
  onClear: () => void;
  onAddLogicSibling: (nodeId: string) => void;
}

const SequenceCanvas: React.FC<Props> = ({ tree, participants, onRemove, onUpdateData, onAddCombo, onAddCondition, onAddDivider, onClear, onAddLogicSibling }) => {
    const { setNodeRef, isOver } = useDroppable({
        id: 'root-canvas',
        data: { type: 'CONTAINER', nodeId: 'root' }
    });

    return (
        <div className="flex flex-col h-full bg-[#050b14] rounded-lg overflow-hidden border border-violet-900/30 shadow-inner">
             <div className="p-2 bg-[#020408] border-b border-violet-900/20 flex items-center gap-2 overflow-x-auto">
                 <button onClick={onAddCombo} className="flex items-center gap-1 px-2 py-1 bg-blue-900/20 text-blue-400 border border-blue-800/50 rounded hover:bg-blue-900/40 text-[10px] uppercase font-bold tracking-wider transition-all whitespace-nowrap">
                    <Box size={12} /> Комбо
                 </button>
                 <button onClick={onAddCondition} className="flex items-center gap-1 px-2 py-1 bg-amber-900/20 text-amber-400 border border-amber-800/50 rounded hover:bg-amber-900/40 text-[10px] uppercase font-bold tracking-wider transition-all whitespace-nowrap">
                    <Split size={12} /> Логика
                 </button>
                 <button onClick={onAddDivider} className="flex items-center gap-1 px-2 py-1 bg-slate-800 text-slate-400 border border-slate-700 rounded hover:bg-slate-700 hover:text-white text-[10px] uppercase font-bold tracking-wider transition-all whitespace-nowrap">
                    <Minus size={12} /> Раздел
                 </button>
                 <div className="flex-1"></div>
                 <button onClick={onClear} className="flex items-center gap-1 px-2 py-1 text-red-500 hover:text-red-300 hover:bg-red-900/10 rounded text-[10px] uppercase font-bold tracking-wider transition-all whitespace-nowrap">
                    <Trash2 size={12} /> Очистить
                 </button>
             </div>

             <div ref={setNodeRef} className={`flex-1 p-4 overflow-y-auto transition-colors ${isOver ? 'bg-violet-900/5' : ''}`}>
                  <SortableContext items={tree.map(n => n.id)} strategy={verticalListSortingStrategy}>
                        {tree.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-50 pointer-events-none">
                                <Zap size={48} className="mb-2" />
                                <span className="text-xs font-mono uppercase tracking-widest">Перетащите способности сюда</span>
                            </div>
                        ) : (
                            tree.map((node, index) => (
                                <CanvasNode 
                                    key={node.id} 
                                    node={node} 
                                    participants={participants} 
                                    onRemove={onRemove} 
                                    onUpdateData={onUpdateData}
                                    index={index}
                                    onAddBranch={onAddLogicSibling}
                                />
                            ))
                        )}
                  </SortableContext>
             </div>
        </div>
    );
};

export default SequenceCanvas;

import React, { useState, useEffect } from 'react';
import { LogEntry, BattleParticipant } from '../types';
import { ChevronLeft, ChevronRight, Clipboard, Save, BarChart3, ScrollText, ListEnd, RotateCcw } from 'lucide-react';
import { generateSummary, generateStatsText } from '../engine/formatters';

interface Props {
  logs: LogEntry[];
  currentRound: number;
  participants: BattleParticipant[];
  onUpdateLogs: (logs: LogEntry[]) => void;
  onUpdateParticipant?: (id: string, updates: any) => void;
  onRollback?: (round: number) => void;
}

type Tab = 'stats' | 'log' | 'summary';

const BattleLog: React.FC<Props> = ({ logs, currentRound, participants, onUpdateLogs, onUpdateParticipant, onRollback }) => {
  const [activeTab, setActiveTab] = useState<Tab>('stats'); 
  const [viewRound, setViewRound] = useState(currentRound);

  const [summaryText, setSummaryText] = useState("");
  const [localLogText, setLocalLogText] = useState("");
  const [localStatsText, setLocalStatsText] = useState("");

  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
      setViewRound(currentRound);
  }, [currentRound]);

  useEffect(() => {
      const roundEntries = logs.filter(l => l.round === viewRound && l.type !== 'round_change' && l.type !== 'system');
      const joinedText = roundEntries.map(l => l.text_formatted).join('\n\n');
      setLocalLogText(joinedText);

      const snapshotLog = logs.find(l => l.round === viewRound && l.details?.participants_snapshot);

      const allEntriesForRound = logs.filter(l => l.round === viewRound);
      const entryWithSummary = allEntriesForRound.reverse().find(l => l.summary !== undefined && l.summary !== null && l.type !== 'system');

      if (entryWithSummary) {
          setSummaryText(entryWithSummary.summary || "");
      } else if (snapshotLog && snapshotLog.summary) {
          setSummaryText(snapshotLog.summary);
      } else {
          if (viewRound === currentRound) {
              setSummaryText(generateSummary(participants, currentRound));
          } else {
              setSummaryText("(Нет сохраненного итога)"); 
          }
      }

      if (!isDirty) {
          if (viewRound === currentRound) {
              setLocalStatsText(generateStatsText(participants));
          } else if (snapshotLog && snapshotLog.details?.stats_snapshot) {
              setLocalStatsText(snapshotLog.details.stats_snapshot);
          } else {
              setLocalStatsText("(Нет сохраненных характеристик)");
          }
      }

      setIsDirty(false);
  }, [viewRound, logs, participants, currentRound]); 

  const handleTextChange = (setter: React.Dispatch<React.SetStateAction<string>>) => (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setter(e.target.value);
      setIsDirty(true);
  };

  const parseAndSaveStats = () => {
      if (!onUpdateParticipant) return;

      const blocks = localStatsText.split(/\n\s*\n/);

      blocks.forEach(block => {
          const lines = block.split('\n').map(l => l.trim()).filter(l => l);
          if (lines.length === 0) return;

          const headerMatch = lines[0].match(/^(.+)\s\(\d+\s*ур\.\)$/i);
          const name = headerMatch ? headerMatch[1].trim() : lines[0].trim();

          // Use profile.name instead of identity.name
          const participant = participants.find(p => p.profile.name === name);
          if (participant) {
              const newStats = { ...participant.stats };

              lines.forEach(line => {
                  const lower = line.toLowerCase();
                  const matchVal = line.match(/:\s*(-?\d+)/);

                  if (matchVal) {
                      const val = parseInt(matchVal[1]);
                      if (!isNaN(val)) {
                          if (lower.startsWith('физ')) newStats.phys = val;
                          else if (lower.startsWith('маг')) newStats.magic = val;
                          else if (lower.startsWith('уник')) newStats.unique = val;
                      }
                  }
              });

              onUpdateParticipant(participant.instance_id, { stats: newStats });
          }
      });
  };

  const saveChanges = () => {
      const otherRoundLogs = logs.filter(l => l.round !== viewRound);
      const roundChangeLog = logs.find(l => l.round === viewRound && l.type === 'round_change');
      const systemLogs = logs.filter(l => l.round === viewRound && l.type === 'system'); 

      const newEntry: LogEntry = {
          id: `edited-${viewRound}-${Date.now()}`,
          round: viewRound,
          timestamp: new Date().toISOString(),
          type: 'action',
          text_formatted: localLogText,
          summary: summaryText 
      };

      const newLogs = [...otherRoundLogs, ...systemLogs];
      if (roundChangeLog) newLogs.push(roundChangeLog); 
      newLogs.push(newEntry);

      newLogs.sort((a, b) => {
           if (a.round !== b.round) return a.round - b.round;
           return 0; 
      });

      onUpdateLogs(newLogs);

      if (activeTab === 'stats') {
          parseAndSaveStats();
      }

      setIsDirty(false);
  };

  const canRollback = viewRound < currentRound && logs.some(l => l.round === viewRound && l.details?.participants_snapshot);

  return (
    <div className="h-full flex flex-col bg-panel rounded-lg shadow-xl border border-violet-900/30 overflow-hidden">

      <div className="flex border-b border-violet-900/30 bg-[#020408]">
          <button 
            onClick={() => setActiveTab('stats')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <BarChart3 size={14} /> Характеристики
          </button>
          <button 
            onClick={() => setActiveTab('log')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'log' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ScrollText size={14} /> Лог
          </button>
          <button 
            onClick={() => setActiveTab('summary')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'summary' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ListEnd size={14} /> Итог
          </button>
      </div>

      <div className="bg-[#050b14] border-b border-violet-900/20 p-2 flex items-center justify-between text-xs">
          <div className="flex items-center gap-2">
              <button 
                onClick={() => setViewRound(Math.max(0, viewRound - 1))}
                disabled={viewRound <= 0}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronLeft size={16} />
              </button>
              <span className="font-bold text-violet-400 uppercase font-rune tracking-widest">{viewRound === 0 ? "Подготовка" : `Раунд ${viewRound}`}</span>
              <button 
                onClick={() => setViewRound(Math.min(currentRound, viewRound + 1))}
                disabled={viewRound >= currentRound}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronRight size={16} />
              </button>
          </div>
          <div className="flex items-center gap-2">
              {canRollback && onRollback && (
                  <button 
                    onClick={() => onRollback(viewRound)}
                    className="flex items-center gap-1 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded px-2 py-1 text-[10px] uppercase font-bold transition-all mr-2"
                    title="Вернуться к состоянию на конец этого раунда"
                  >
                      <RotateCcw size={10} /> Переиграть сл.
                  </button>
              )}

              {isDirty && (
                  <button 
                    onClick={saveChanges}
                    className="flex items-center gap-1 text-emerald-400 hover:text-emerald-300 font-bold animate-pulse uppercase text-[10px] tracking-wider"
                  >
                      <Save size={12} /> Сохранить
                  </button>
              )}
          </div>
      </div>

      <div className="flex-1 bg-[#020408] relative overflow-hidden flex flex-col">

         {activeTab === 'stats' && (
             <div className="h-full flex flex-col">
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 outline-none resize-none font-mono text-xs leading-relaxed selection:bg-violet-900/50"
                    value={localStatsText}
                    onChange={handleTextChange(setLocalStatsText)}
                    spellCheck={false}
                    placeholder="Данные участников..."
                 />
             </div>
         )}

         {activeTab === 'log' && (
             <textarea 
                className="w-full h-full bg-[#020408] text-slate-300 p-4 outline-none resize-none font-mono text-xs leading-relaxed selection:bg-violet-900/50"
                value={localLogText}
                onChange={handleTextChange(setLocalLogText)}
                spellCheck={false}
                placeholder="Лог раунда пуст..."
             />
         )}

         {activeTab === 'summary' && (
             <div className="h-full flex flex-col">
                 <div className="p-2 bg-violet-900/10 text-[10px] text-slate-500 uppercase tracking-widest border-b border-violet-900/20 flex justify-between items-center">
                     <span>Сводка (Раунд {viewRound})</span>
                     <button onClick={() => navigator.clipboard.writeText(summaryText)} title="Копировать" className="hover:text-white"><Clipboard size={12}/></button>
                 </div>
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 text-xs font-mono outline-none resize-none selection:bg-emerald-900/50"
                    value={summaryText}
                    onChange={handleTextChange(setSummaryText)}
                    placeholder={viewRound < currentRound && !summaryText ? "(Нет сохраненного итога)" : "Здесь будет сводка раунда..."}
                    spellCheck={false}
                 />
             </div>
         )}
      </div>
    </div>
  );
};

export default BattleLog;

import { BattleParticipant, SequenceNode, JsonAbility, JsonItem, JsonBonus, InjuryRule } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';

interface CalculationResult {
  formattedString: string;
}

const DEFAULT_INJURY_RULES: InjuryRule[] = Object.entries(TRAUMA_DEFINITIONS).map(([tag, def]) => ({
    tag,
    label: def.label,
    value: def.value,
    stack: def.stack
}));

const normalizeTags = (tags: string[] = []) => tags.map(t => t.toLowerCase().trim());

const hasTagOverlap = (sourceTags: string[], targetTags: string[]): boolean => {
    if (!sourceTags || sourceTags.length === 0) return true; 
    return sourceTags.some(t => targetTags.includes(t));
};

const sumBonuses = (bonuses: JsonBonus[] = []): number => {
    return bonuses.reduce((acc, b) => acc + (Number(b.val) || 0), 0);
};

const calculateLiveStatPenalty = (
    participant: BattleParticipant, 
    statType: 'phys' | 'magic' | 'unique',
    rules: InjuryRule[]
): number => {
    // Uses medcard
    if (!participant.medcard || !participant.medcard.injuries) return 0;

    let totalPenalty = 0;
    const suffix = `_${statType === 'unique' ? 'uniq' : statType}`; 

    const injuryCounts: Record<string, number> = {};
    participant.medcard.injuries.forEach(inj => {
        const tag = inj.template_id;
        if (tag.endsWith(suffix)) {
            injuryCounts[tag] = (injuryCounts[tag] || 0) + (inj.count || 1);
        }
    });

    Object.entries(injuryCounts).forEach(([tag, count]) => {
        const rule = rules.find(r => r.tag === tag);
        if (rule) {
            const penaltyValue = Number(rule.value);
            const stackSize = Number(rule.stack);

            if (stackSize > 0) {
                const stacksApplied = Math.floor(count / stackSize);
                totalPenalty += (stacksApplied * penaltyValue);
            } else {
                totalPenalty += (count * penaltyValue);
            }
        }
    });

    return totalPenalty;
};

export const getMatchingFactors = (
    participant: BattleParticipant,
    abilityTags: string[]
) => {
    const factors: { name: string, bonus: number, type: 'passive' | 'effect' | 'item', tags?: string[], desc?: string, mech?: string }[] = [];
    const normalizedAbilityTags = normalizeTags(abilityTags);

    if (participant.flat_passives) {
        participant.flat_passives.forEach(pas => {
            const isAlways = !pas.trigger || pas.trigger.toLowerCase() === 'always' || pas.trigger === 'Пассивно / Всегда';
            if (isAlways && hasTagOverlap(normalizeTags(pas.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: pas.name, 
                    bonus: sumBonuses(pas.bonuses), 
                    type: 'passive', 
                    tags: pas.tags,
                    mech: pas.desc_mech 
                });
            }
        });
    }

    if (participant.active_effects) {
        participant.active_effects.forEach(eff => {
            if (hasTagOverlap(normalizeTags(eff.tags), normalizedAbilityTags)) {
                let mechanics = '';
                if (eff.original_ability_id) {
                    const source = participant.flat_abilities.find(a => a._id === eff.original_ability_id);
                    if (source) mechanics = source.desc_mech || '';
                }

                factors.push({ 
                    name: eff.name, 
                    bonus: sumBonuses(eff.bonuses), 
                    type: 'effect', 
                    tags: eff.tags,
                    desc: `Active effect. Duration: ${eff.duration_left} ${eff.unit}`,
                    mech: mechanics
                });
            }
        });
    }

    if (participant.equipment && participant.equipment.wearable) {
        participant.equipment.wearable.forEach(item => {
            if (item.is_equipped && hasTagOverlap(normalizeTags(item.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: item.name, 
                    bonus: sumBonuses(item.bonuses), 
                    type: 'item', 
                    tags: item.tags,
                    mech: item.desc_mech,
                    desc: item.desc_lore
                });
            }
        });
    }

    return factors;
};

const calculateTotalBonus = (
    participant: BattleParticipant, 
    ability: JsonAbility, 
    weapon: JsonItem | undefined,
    injuryRules: InjuryRule[],
    excludedModifiers: string[] = []
): number => {
    let total = 0;

    const usedStats = new Set<string>();
    if (ability.bonuses) {
        ability.bonuses.forEach(b => {
            const bonusVal = Number(b.val) || 0;
            if (b.stat) {
                const statKey = b.stat.toLowerCase();
                if (statKey.includes('phys') || statKey.includes('физ')) {
                    if (!usedStats.has('phys')) {
                        const base = Number(participant.stats.phys) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'phys', injuryRules));
                        usedStats.add('phys');
                    }
                } 
                if (statKey.includes('mag') || statKey.includes('маг')) {
                    if (!usedStats.has('magic')) {
                        const base = Number(participant.stats.magic) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'magic', injuryRules));
                        usedStats.add('magic');
                    }
                } 
                if (statKey.includes('uniq') || statKey.includes('уник')) {
                    if (!usedStats.has('unique')) {
                        const base = Number(participant.stats.unique) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'unique', injuryRules));
                        usedStats.add('unique');
                    }
                }
            }
            total += bonusVal;
        });
    }

    if (weapon) total += sumBonuses(weapon.bonuses);

    const externalFactors = getMatchingFactors(participant, ability.tags);
    externalFactors.forEach(f => {
        if (!excludedModifiers.includes(f.name)) {
            total += f.bonus;
        }
    });

    return total;
};

const getDiceString = (level: number = 1): string => {
    if (level >= 5) return '3d100';
    if (level >= 3) return '2d100';
    return '1d100';
};

export const calculateSequenceTree = (
  nodes: SequenceNode[],
  participants: BattleParticipant[],
  injuryRules: InjuryRule[] = DEFAULT_INJURY_RULES 
): CalculationResult => {

  const getActionData = (charId: string, abilityId: string, weaponId?: string, excludedModifiers: string[] = []) => {
        const actor = participants.find(p => p.instance_id === charId || p.id === charId);
        if (!actor) return null;

        let ability = actor.flat_abilities?.find(a => a._id === abilityId);
        if (!ability && actor.ability_groups) {
            for (const group of actor.ability_groups) {
                const found = group.abilities.find(a => a._id === abilityId || (a.id && a.id === abilityId) || a.name === abilityId);
                if (found) { ability = found; break; }
            }
        }

        if (!ability) return null;

        const weapon = actor.equipment.usable.find(w => w._id === weaponId || (w.id && w.id === weaponId) || w.name === weaponId);

        const bonusVal = calculateTotalBonus(actor, ability, weapon, injuryRules, excludedModifiers);
        const sign = bonusVal >= 0 ? '+' : '';
        const weaponStr = weapon ? ` [${weapon.name}]` : '';
        const nameStr = `${ability.name}${weaponStr}`;
        // Use profile.level
        const diceStr = getDiceString(actor.profile.level);

        const isUtility = ability.tags.some(t => ['buff', 'form', 'бафф', 'форма'].includes(t.toLowerCase()));

        return { 
            name: nameStr, 
            actorName: actor.profile.name,
            bonus: `${sign}${bonusVal}`, 
            dice: diceStr, 
            hideResult: isUtility,
            mechanics: ability.desc_mech
        };
  };

  const processNode = (node: SequenceNode): string => {
    if (node.type === 'divider') return '\n';

    if (node.type === 'logic_chain') {
        const childrenStr = node.children.map(c => processNode(c)).join(' | ');
        return `\n{ ${childrenStr} }`;
    }

    if (node.type === 'condition') {
      const conditionText = node.data?.conditionText || '...';
      const childStrings = node.children.map(c => processNode(c)).filter(s => s && s.trim() !== '');
      let innerContent = childStrings.join(' - ');
      return `${conditionText}: ${innerContent}`;
    }

    if (node.type === 'combo') {
      const validChildren = node.children.filter(c => c.type === 'action');
      if (validChildren.length === 0) return '';

      const dataList = validChildren.map(c => 
          getActionData(c.data?.charId || '', c.data?.abilityId || '', c.data?.weaponId, c.data?.excludedModifiers)
      ).filter(Boolean) as any[];

      if (dataList.length === 0) return '';

      const actorName = dataList[0].actorName;
      const names = dataList.map(d => d.name).join(' + ');

      const visibleDataList = dataList.filter(d => !d.hideResult);

      if (visibleDataList.length === 0) {
           const mechanicsStr = dataList.map(d => d.mechanics || '').filter(Boolean).join(' + ');
           return `${actorName}: [${names}]${mechanicsStr ? `(${mechanicsStr})` : ''}`;
      }

      const bonuses = visibleDataList.map(d => `${d.dice}${d.bonus}`).join('/');
      return `${actorName}: [${names}](${bonuses})`;
    }

    if (node.type === 'action') {
        const data = getActionData(node.data?.charId || '', node.data?.abilityId || '', node.data?.weaponId, node.data?.excludedModifiers);
        if (!data) return '[Unknown Action]';

        if (data.hideResult) {
            return `(${data.actorName}: ${data.name}${data.mechanics ? `(${data.mechanics})` : ''})`;
        }
        return `${data.actorName}: ${data.name}(${data.dice}${data.bonus})`;
    }

    return '';
  };

  const parts = nodes.map(n => processNode(n)).filter(Boolean);

  let finalString = '';

  parts.forEach((part, index) => {
      const cleanPart = part.trimEnd();

      if (index === 0) {
          if (cleanPart.startsWith('\n')) {
              finalString += '> ' + cleanPart.trimStart(); 
          } else {
              finalString += '> ' + cleanPart;
          }
      } else {
          if (finalString.endsWith('\n') || cleanPart.startsWith('\n')) {
              if (cleanPart.startsWith('\n')) {
                  finalString += '\n> ' + cleanPart.trimStart();
              } else {
                  finalString += '> ' + cleanPart; 
              }
          } else {
               finalString += ' - ' + cleanPart;
          }
      }
  });

  return { formattedString: finalString };
};

import { BattleParticipant } from '../types';
import { formatCooldown, formatDuration, STATUS_PHRASES } from '../constants';

const getStatusPhrase = (phrases: string[], seed: number) => {
    if (!phrases || phrases.length === 0) return "Неизвестно";
    return phrases[seed % phrases.length];
};

export const generateSummary = (participants: BattleParticipant[], round: number): string => {
    let text = "";

    // 1. Status Section
    participants.forEach(p => {
        const { trauma_phys = 0, trauma_mag = 0, trauma_uniq = 0 } = p.battle_stats;
        let phrase = "";

        const charSeed = p.instance_id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
        const seed = Math.abs(charSeed + trauma_phys + round);

        if (trauma_phys === 0) {
            phrase = getStatusPhrase(STATUS_PHRASES.level_0, seed);
        } else {
            const positiveTrauma = Math.abs(trauma_phys);
            const level = Math.ceil(positiveTrauma / 5) * 5;
            const lookupKey = level > 60 ? 'level_60' : `level_${level}`;
            const phraseSet = STATUS_PHRASES[lookupKey] || STATUS_PHRASES.level_60;
            phrase = getStatusPhrase(phraseSet, seed);
        }

        const parts: string[] = [];
        if (trauma_phys !== 0) parts.push(`Физ: ${trauma_phys}`);
        if (trauma_mag !== 0) parts.push(`Маг: ${trauma_mag}`);
        if (trauma_uniq !== 0) parts.push(`Уник: ${trauma_uniq}`);

        const injuriesText = parts.length > 0 ? `(${parts.join(', ')})` : "";
        text += `${p.profile.name} — ${phrase} ${injuriesText}\n\n`;
    });

    // 2. Split Effects
    const forms: string[] = [];
    const buffs: string[] = [];
    const debuffs: string[] = [];

    participants.forEach(p => {
        p.active_effects.forEach(eff => {
             const isForm = (eff.tags || []).some(t => t.toLowerCase().includes('form') || t.toLowerCase().includes('форма'));
             const isNegative = eff.bonuses.some(b => b.val < 0);

             const line = `${eff.name} (${p.profile.name}) — ${formatDuration(eff.duration_left, eff.unit)}`;

             if (isForm) forms.push(line);
             else if (isNegative) debuffs.push(line);
             else buffs.push(line);
        });
    });

    if (forms.length > 0) {
        text += "Активные Формы:\n" + forms.join('\n') + "\n\n";
    }

    if (buffs.length > 0) {
        text += "Активные Баффы:\n" + buffs.join('\n') + "\n\n";
    }

    if (debuffs.length > 0) {
        text += "Активные Ослабления:\n" + debuffs.join('\n') + "\n\n";
    }

    if (forms.length === 0 && buffs.length === 0 && debuffs.length === 0) {
        text += "(Нет активных эффектов)\n\n";
    }

    text += "Перезарядка:\n";
    const battleCDs: string[] = [];
    participants.forEach(p => {
        p.cooldowns.forEach(cd => {
             battleCDs.push(`${cd.name} (${p.profile.name}): ${formatCooldown(cd.name, cd.val, cd.unit)}`);
        });
    });

    if (battleCDs.length > 0) text += battleCDs.join('\n') + '\n';
    return text;
};

export const generateStatsText = (participants: BattleParticipant[]) => {
    return participants.map(p => {
        const lines = [];
        // Header: "Name (X ур.)"
        lines.push(`${p.profile.name} (${p.profile.level} ур.)`);

        const pT = p.battle_stats.trauma_phys;
        const mT = p.battle_stats.trauma_mag;
        const uT = p.battle_stats.trauma_uniq;

        lines.push(`Физическая характеристика: ${p.stats.phys}${pT !== 0 ? ` (${pT})` : ''}`);
        lines.push(`Магическая характеристика: ${p.stats.magic}${mT !== 0 ? ` (${mT})` : ''}`);
        lines.push(`Уникальная характеристика: ${p.stats.unique}${uT !== 0 ? ` (${uT})` : ''}`);

        const permanentPassives = p.flat_passives.filter(pas => {
            const t = (pas.trigger || '').toLowerCase().trim();
            return !t || t === 'always' || t === 'passive' || t === 'пассивно' || t === 'всегда' || t === 'пассивно / всегда';
        });

        if (permanentPassives.length > 0) {
            lines.push(`> Пассивные эффекты:`);
            permanentPassives.forEach(pas => {
                lines.push(`${pas.name} (${pas.desc_mech || 'нет описания'})`);
            });
        }

        const forms = [];
        const buffs = [];
        const debuffs = [];

        p.active_effects.forEach(e => {
            const isForm = (e.tags || []).some(t => t.toLowerCase().includes('form') || t.toLowerCase().includes('форма'));

            const isNegative = e.bonuses.some(b => b.val < 0);

            const line = `${e.name} (ост. ${formatDuration(e.duration_left, e.unit)})`;

            if (isForm) forms.push(line);
            else if (isNegative) debuffs.push(line);
            else buffs.push(line);
        });

        if (forms.length > 0) {
            lines.push(`> Формы:`);
            forms.forEach(l => lines.push(l));
        }

        if (buffs.length > 0) {
            lines.push(`> Баффы:`);
            buffs.forEach(l => lines.push(l));
        }

        if (debuffs.length > 0) {
            lines.push(`> Ослабления:`);
            debuffs.forEach(l => lines.push(l));
        }

        return lines.join('\n');
    }).join('\n\n\n');
};

