  [StatType.PHYS]: "text-red-400 drop-shadow-[0_0_8px_rgba(248,113,113,0.5)]",
  [StatType.MAGIC]: "text-violet-400 drop-shadow-[0_0_8px_rgba(167,139,250,0.5)]",
  [StatType.UNIQUE]: "text-emerald-400 drop-shadow-[0_0_8px_rgba(52,211,153,0.5)]"
};

export const StatBg = {
  [StatType.PHYS]: "bg-red-950/30 border-red-900/40",
  [StatType.MAGIC]: "bg-violet-950/30 border-violet-900/40",
  [StatType.UNIQUE]: "bg-emerald-950/30 border-emerald-900/40"
