import { supabase } from '../lib/supabase';
import { CharacterData, InjuryDefinition, TimeUnit } from '../types';
import { DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from '../constants';

export const getAllCharacters = async (): Promise<CharacterData[]> => {
  try {
    console.log('Fetching characters...');
    const { data, error } = await supabase.from('characters').select('*');

    if (error) {
      console.error("Supabase fetch error (characters):", error);
      return [];
    }

    if (!data) return [];

    const validChars: CharacterData[] = [];

    data.forEach((row: any) => {
      let charData = row.data || row;
      if (!charData.id) charData.id = row.id;

      // --- STRICT FILTERING ---
      // 1. If 'profile' is missing, it's a legacy character or invalid. Skip it.
      // We do NOT map 'identity' anymore as requested.
      if (!charData.profile) {
          return; 
      }

      // --- HYDRATION & DEFAULTS ---
      // Ensure all nested objects exist to prevent "cannot read property of undefined" errors in UI.

      // Profile & Currencies
      if (!charData.profile.currencies) {
          charData.profile.currencies = { juhe: 0, jumi: 0 };
      }

      // Meta
      if (!charData.meta) {
          charData.meta = { uid: 'system', owner_link: '', avatar_url: '', save_status: true };
      }

      // Stats
      if (!charData.stats) {
          charData.stats = { phys: 0, magic: 0, unique: 0 };
      }

      // Equipment - Handle missing object OR missing nested arrays
      if (!charData.equipment) {
          charData.equipment = { usable: [], wearable: [], inventory: [] };
      } else {
          // Careful hydration for existing object
          if (!Array.isArray(charData.equipment.wearable)) charData.equipment.wearable = [];
          if (!Array.isArray(charData.equipment.usable)) charData.equipment.usable = [];
          if (!Array.isArray(charData.equipment.inventory)) charData.equipment.inventory = [];
      }

      // Arrays
      if (!Array.isArray(charData.ability_groups)) charData.ability_groups = [];
      if (!Array.isArray(charData.passives)) charData.passives = [];
      if (!Array.isArray(charData.resources)) charData.resources = [];

      // Medcard (Handle migration from med_card if strictly necessary, otherwise default)
      if (!charData.medcard) {
          charData.medcard = charData.med_card || { injuries: [], conditions: [] };
      }
      if (!Array.isArray(charData.medcard.injuries)) charData.medcard.injuries = [];
      if (!Array.isArray(charData.medcard.conditions)) charData.medcard.conditions = [];

      validChars.push(charData as CharacterData);
    });

    return validChars;
  } catch (error) {
    console.warn("Could not fetch characters.", error);
    return [];
  }
};

export const saveCharacter = async (char: CharacterData) => {
  if (!char.id) {
    throw new Error("Critical Error: Character ID missing before save attempt.");
  }

  // Clean up legacy fields to keep DB clean
  const payload = { ...char };
  // @ts-ignore
  delete payload.identity; 
  // @ts-ignore
  delete payload.med_card;

  const { data, error } = await supabase
    .from('characters')
    .upsert({ 
      id: char.id, 
      data: payload 
    })
    .select();

  if (error) {
    console.error("Supabase Save Error:", error);
    throw new Error(`Database Error: ${error.message}`);
  }

  return true;
};

export const deleteCharacter = async (id: string) => {
  const { error } = await supabase.from('characters').delete().eq('id', id);
  if (error) throw new Error(error.message);

  // Cascade delete units using the JSON path to master_id in meta
  const { error: cascadeError } = await supabase
    .from('characters')
    .delete()
    .eq('data->meta->>master_id', id);

  if (cascadeError) console.error("Failed to cascade delete minions", cascadeError);
};

export const uploadAvatar = async (file: File): Promise<string> => {
  const MAX_SIZE = 10 * 1024 * 1024;
  if (file.size > MAX_SIZE) throw new Error("Файл слишком большой. Максимум 10 МБ.");

  const fileExt = file.name.split('.').pop();
  const fileName = `avatar_${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
  const filePath = `${fileName}`;

  const { error: uploadError } = await supabase.storage.from('Juul-D-Tracker').upload(filePath, file);
  if (uploadError) throw new Error("Ошибка при загрузке изображения.");

  const { data } = supabase.storage.from('Juul-D-Tracker').getPublicUrl(filePath);
  return data.publicUrl;
};

export const getGlobalTriggers = async (): Promise<Record<string, string>> => {
  try {
    const { data } = await supabase.from('triggers').select('tag, label');
    if (!data || data.length === 0) return { "Always": "Пассивно / Всегда" };
    const map: Record<string, string> = {};
    data.forEach((row: any) => { map[row.tag] = row.label; });
    return map;
  } catch (error) {
    return { "Always": "Пассивно / Всегда" };
  }
};

export const saveGlobalTriggers = async (triggers: Record<string, string>) => {
  const rows = Object.entries(triggers).map(([tag, label]) => ({ tag, label }));
  if (rows.length > 0) await supabase.from('triggers').upsert(rows);
};

export const getInjuries = async (): Promise<InjuryDefinition[]> => {
  try {
    const { data } = await supabase.from('injuries').select('*').order('type').order('value');
    if (!data || data.length === 0) return DEFAULT_INJURIES;
    return data as InjuryDefinition[];
  } catch (error) {
    return DEFAULT_INJURIES;
  }
};

export const saveInjuries = async (injuries: InjuryDefinition[]) => {
  if (injuries.length > 0) await supabase.from('injuries').upsert(injuries);
};

export const getTimeUnits = async (): Promise<TimeUnit[]> => {
  try {
    const { data } = await supabase.from('time_units').select('tag, label, battle');
    if (!data || data.length === 0) return DEFAULT_TIME_UNITS;
    return data.map((r: any) => ({ tag: r.tag || r.label, label: r.label, battle: r.battle || false }));
  } catch (error) {
    return DEFAULT_TIME_UNITS;
  }
};

export const saveTimeUnits = async (units: TimeUnit[]) => {
  const rows = units.map(u => ({ tag: u.tag, label: u.label, battle: u.battle }));
  if (rows.length > 0) await supabase.from('time_units').upsert(rows, { onConflict: 'tag' });
};

import React from 'react';
import { CharacterData } from '../types';
import { Card, SectionHeader, StyledInput, StyledTextarea, Button, BonusInput, TagInput } from './Shared';
import { Plus, Trash2, Shield, Sword, Package } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (eq: CharacterData['equipment']) => void;
  onInstantUpdate: (eq: CharacterData['equipment']) => void;
}

const TabEquipment: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, onInstantUpdate }) => {
  const { equipment } = character;
  const { isAdmin } = useAuth();
  /* [DIALECT] */ const { t } = useDialect();

  // Safety fallback
  const wearable = equipment?.wearable || [];
  const usable = equipment?.usable || [];
  const inventory = equipment?.inventory || [];

  const updateList = (key: keyof typeof equipment, idx: number, val: any) => {
    // Ensure array exists when trying to update
    const list = [...(equipment[key] || [])] as any[];
    list[idx] = val;
    onChange({ ...equipment, [key]: list });
  };

  const addItem = (key: keyof typeof equipment) => {
    // Ensure array exists when trying to add
    const list = [...(equipment[key] || [])] as any[];
    const templates: any = {
      wearable: { name: 'Новая Броня', bonuses: [], tags: [], is_equipped: false, desc_lore: '', desc_mech: '' },
      usable: { name: 'Новое Оружие', bonuses: [], tags: [], desc_lore: '', desc_mech: '' },
      inventory: { name: 'Предмет', desc_lore: '', desc_mech: '', qty: 1 }
    };
    list.push(templates[key]);
    onChange({ ...equipment, [key]: list });
  };

  const remove = (key: keyof typeof equipment, idx: number) => {
    const list = [...(equipment[key] || [])] as any[];
    list.splice(idx, 1);
    onChange({ ...equipment, [key]: list });
  };

  const handleEquipToggle = (idx: number, currentItem: any) => {
    const newVal = !currentItem.is_equipped;

    if (isEditMode) {
      updateList('wearable', idx, { ...currentItem, is_equipped: newVal });
    } else {
      const list = [...wearable];
      list[idx] = { ...currentItem, is_equipped: newVal };
      onInstantUpdate({ ...equipment, wearable: list });
    }
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-fade-in">

      {/* Wearable */}
      <div className="space-y-4">
        {/* [DIALECT] */}
        <SectionHeader title={t('eq_wearable', "Экипировка")}>
