             <div className="space-y-2 mt-2">
                {(shouldShowLore || isEditMode) && (
                  <StyledTextarea 
                    isEditMode={isEditMode} 
                    value={item.desc_lore} 
                    onChange={e => updateList('wearable', i, {...item, desc_lore: e.target.value})} 
                    className="text-sm text-gray-500 italic" 
