            <option value="">Ед.</option>
            {options.map(u => <option key={u.tag} value={u.tag}>{u.label}</option>)}
          </select>
        </>
      ) : (
        <span className="text-slate-400 font-medium">
          {translatedLabel}: <span className="text-violet-200">{val} {displayLabel}</span>
        </span>
      )}
    </div>
  );
};

