export const TimeInput = ({ 
  label, val, unit, onChangeVal, onChangeUnit, isEditMode, icon: Icon, options = []
}: { label: string, val: number, unit: string, onChangeVal: (v: number) => void, onChangeUnit: (u: string) => void, isEditMode: boolean, icon: any, options?: TimeUnit[] }) => {

  /* [DIALECT] */ const { t } = useDialect();

  if (!isEditMode && (!val && !unit)) return null;

  const displayLabel = options.find(o => o.tag === unit)?.label || unit;
  const translatedLabel = label === 'КД' ? t('lbl_cd', 'КД') : 
                          label === 'Длит.' ? t('lbl_dur', 'Длит.') : 
                          label === 'Лимит' ? t('lbl_limit', 'Лимит') : label;

  return (
    <div className="flex items-center gap-2 text-xs bg-[#0f172a] rounded-sm border border-violet-900/30 px-2 py-1 shadow-sm">
      <Icon size={12} className="text-violet-500" />
      {isEditMode ? (
        <>
          <span className="text-slate-500 text-[10px] font-serif uppercase mr-1">{translatedLabel}:</span>
          <input type="number" value={val || ""} onChange={e => onChangeVal(parseFloat(e.target.value) || 0)} className="w-8 bg-transparent border-b border-slate-700 text-center text-slate-200 focus:border-violet-500 outline-none" placeholder="0" />
          <select value={unit} onChange={e => onChangeUnit(e.target.value)} className="bg-transparent text-slate-400 border-none p-0 focus:ring-0 max-w-[80px] text-[10px]">
            <option value="">Ед.</option>
            {options.map(u => <option key={u.tag} value={u.tag}>{u.label}</option>)}
          </select>
        </>
      ) : (
        <span className="text-slate-400 font-medium">
          {translatedLabel}: <span className="text-violet-200">{val} {displayLabel}</span>
        </span>
      )}
    </div>
  );
};

// --- Complex Components ---

export const TagInput = ({ tags, onChange, isEditMode }: { tags: string[], onChange: (t: string[]) => void, isEditMode: boolean }) => {
  /* [DIALECT] */ const { t } = useDialect();
  if (!isEditMode) return null;

  const [input, setInput] = useState("");
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && input.trim()) {
      e.preventDefault();
      onChange([...tags, input.trim()]);
      setInput("");
    }
  };
  const removeTag = (idx: number) => onChange(tags.filter((_, i) => i !== idx));

  return (
    <div className="flex flex-wrap gap-2 items-center">
      {tags.map((t, i) => (
        <span key={i} className="bg-violet-950/50 text-violet-300 border border-violet-800/50 px-2 py-0.5 rounded-sm text-[10px] uppercase font-bold flex items-center gap-1">
          {t}
          {isEditMode && <button onClick={() => removeTag(i)}><Trash2 size={10} /></button>}
        </span>
      ))}
      {isEditMode && (
        <input 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={t('ph_tag_add', "+Тег")}
          className="bg-transparent border-b border-slate-700 text-xs py-0.5 w-16 focus:w-24 transition-all focus:border-violet-500 outline-none text-slate-400 placeholder:text-slate-700"
        />
      )}
    </div>
  );
};

export const CommonTagToggles = ({ tags = [], onChange }: { tags: string[], onChange: (t: string[]) => void }) => {
  /* [DIALECT] */ const { t } = useDialect();

  const toggle = (tag: string) => {
    if (tags.includes(tag)) {
      onChange(tags.filter(curr => curr !== tag));
    } else {
      onChange([...tags, tag]);
    }
  };

  // Reverted to Standard Russian for default view
  const checkboxes = [
    { key: 'buff', label: t('tag_buff', 'Бафф?') },
    { key: 'form', label: t('tag_form', 'Форма?') },
    { key: 'no_war', label: t('tag_no_war', 'Небоевое?') },
  ];

  return (
    <div className="flex gap-4 items-center mt-2 border-t border-violet-900/20 pt-2">
      {checkboxes.map(cb => (
        <label key={cb.key} className="flex items-center gap-1.5 cursor-pointer text-xs group select-none">
          <input 
            type="checkbox" 
            checked={tags.includes(cb.key)} 
            onChange={() => toggle(cb.key)}
            className="w-3.5 h-3.5 rounded-sm border-slate-600 bg-slate-900 text-violet-600 focus:ring-offset-0 focus:ring-0 cursor-pointer"
          />
          <span className={`font-bold font-serif transition-colors ${tags.includes(cb.key) ? 'text-violet-400' : 'text-slate-600 group-hover:text-slate-400'}`}>
            {cb.label}
          </span>
        </label>
      ))}
    </div>
  );
};

export const BonusInput = ({ bonuses, onChange, isEditMode }: { bonuses: Bonus[], onChange: (b: Bonus[]) => void, isEditMode: boolean }) => {
  const addBonus = () => onChange([...bonuses, { stat: StatType.PHYS, val: 1 }]);
  /* [DIALECT] */ const { t } = useDialect();

  const updateBonus = (idx: number, field: keyof Bonus, val: any) => {
    const next = [...bonuses];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };
  const removeBonus = (idx: number) => onChange(bonuses.filter((_, i) => i !== idx));

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap gap-2">
        {bonuses.map((b, i) => (
          <div key={i} className={`flex items-center gap-1 px-2 py-0.5 rounded-sm text-xs border ${getStatBgClass(b.stat)} ${getStatColorClass(b.stat)}`}>
            {isEditMode ? (
              <>
                 <select 
                   value={b.stat} 
                   onChange={(e) => updateBonus(i, 'stat', e.target.value)}
                   className="bg-transparent border-none p-0 text-[10px] font-bold focus:ring-0 cursor-pointer text-slate-300 uppercase"
                 >
                   <option value={StatType.PHYS}>{t('stat_phys_short', 'ФИЗ')}</option>
                   <option value={StatType.MAGIC}>{t('stat_mag_short', 'МАГ')}</option>
                   <option value={StatType.UNIQUE}>{t('stat_uni_short', 'УНИК')}</option>
                 </select>
                 <span className="text-slate-500">:</span>
                 <input 
                   type="number" 
                   value={b.val} 
                   onChange={(e) => updateBonus(i, 'val', parseInt(e.target.value))}
                   className="w-8 bg-transparent border-b border-slate-600 text-center font-mono text-slate-200"
                 />
                 <button onClick={() => removeBonus(i)} className="text-red-400 hover:text-red-300 ml-1"><Trash2 size={10} /></button>
              </>
            ) : (
              <span className="flex items-center gap-1 font-mono font-bold">
                {StatIcons[b.stat] || <Sword size={12}/>} {b.val > 0 ? '+' : ''}{b.val}
              </span>
            )}
          </div>
        ))}
        {isEditMode && (
          <button onClick={addBonus} className="text-xs bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded px-2 py-0.5 flex items-center gap-1">
            <Plus size={10} /> {t('lbl_bonus', 'Бонус')}
          </button>
        )}
      </div>
    </div>
  );
};

// --- Visualization Charts ---

export const TabRadarCharts = ({ groups, isDebuff = false, color }: { groups: { name: string, items: { bonuses: Bonus[] }[] }[], isDebuff?: boolean, color?: string }) => {
  /* [DIALECT] */ const { t } = useDialect();

  if (!groups || groups.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center h-32 border border-violet-900/20 border-dashed rounded-lg bg-violet-900/5 mb-6 text-slate-600 gap-2">
            <Ghost size={24} className="opacity-30" />
            <span className="text-[10px] uppercase font-bold tracking-widest">{t('msg_chart_empty', 'Пусто')}</span>
        </div>
      );
  }

  const structureData = groups.map((g, i) => {
    const name = g.name || "Unknown"; // Fallback name
    let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
    return {
      subject: baseName + '\u200B'.repeat(i), 
      value: g.items ? g.items.length : 0
    };
  });

  while (structureData.length < 3) {
      structureData.push({ 
          subject: '\u200B'.repeat(100 + structureData.length), 
          value: 0 
      });
  }

  const maxStructureVal = Math.max(...structureData.map(d => d.value), 3);

  let phys = 0, magic = 0, unique = 0;
  groups.forEach(g => {
    if (Array.isArray(g.items)) {
      g.items.forEach(item => {
        if (Array.isArray(item.bonuses)) {
          item.bonuses.forEach(b => {
             const val = Number(b.val);
             if (!Number.isNaN(val)) {
                if (b.stat === StatType.PHYS) phys += val;
                if (b.stat === StatType.MAGIC) magic += val;
                if (b.stat === StatType.UNIQUE) unique += val;
             }
          });
        }
      });
    }
  });

  const getValue = (v: number) => isDebuff ? Math.abs(v) : Math.max(0, v);

  const bonusData = [
    { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
    { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
    { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
  ];

  const maxBonusVal = Math.max(...bonusData.map(d => d.value), 5);

  const defaultColor = isDebuff ? "#ef4444" : "#8b5cf6"; // Red or Violet
  const mainColor = color || defaultColor;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 h-auto">

       <div className="bg-[#050b14] border border-violet-900/20 shadow-md p-2 relative h-48 flex flex-col rune-clip-r">
          <div className="absolute top-2 left-3 text-[9px] font-bold text-slate-500 uppercase tracking-widest z-10 font-serif">
             {t('viz_structure', 'Структура')}
          </div>
          {/* Fix: explicit pixel min-height/width on parent div to prevent Recharts calculation errors */}
          <div style={{ width: '100%', height: '100%', minHeight: '160px', minWidth: '200px', position: 'relative' }}>
            <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
                <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="65%" data={structureData}>
                    <PolarGrid stroke="#334155" strokeOpacity={0.4} />
                    <PolarAngleAxis 
                    dataKey="subject" 
                    tick={{ fill: '#64748b', fontSize: 9, fontFamily: 'Cinzel' }} 
                    />
                    <PolarRadiusAxis 
                    angle={30} 
                    domain={[0, maxStructureVal]} 
                    tick={false} 
                    axisLine={false} 
                    />
                    <Radar
                    name="Count"
                    dataKey="value"
                    stroke={mainColor}
                    strokeWidth={2}
                    fill={mainColor}
                    fillOpacity={0.2}
                    isAnimationActive={false}
                    />
                </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
       </div>

       <div className="bg-[#050b14] border border-violet-900/20 shadow-md p-2 relative h-48 flex flex-col rune-clip-r">
          <div className="absolute top-2 left-3 text-[9px] font-bold text-slate-500 uppercase tracking-widest z-10 font-serif">
             {isDebuff ? t('viz_penalties', "Штрафы") : t('viz_bonuses', "Бонусы")}
          </div>
          {/* Fix: explicit pixel min-height/width on parent div to prevent Recharts calculation errors */}
          <div style={{ width: '100%', height: '100%', minHeight: '160px', minWidth: '200px', position: 'relative' }}>
            <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
                <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="65%" data={bonusData}>
                    <PolarGrid stroke="#334155" strokeOpacity={0.4} />
                    <PolarAngleAxis 
                    dataKey="subject" 
                    tick={{ fill: mainColor, fontSize: 10, fontWeight: 'bold', fontFamily: 'Cinzel' }} 
                    />
                    <PolarRadiusAxis 
                    angle={30} 
                    domain={[0, maxBonusVal]} 
                    tick={false} 
                    axisLine={false} 
                    />
                    <Radar
                    name="Sum"
                    dataKey="value"
                    stroke={mainColor}
                    strokeWidth={2}
                    fill={mainColor}
                    fillOpacity={0.2}
                    isAnimationActive={false}
                    />
                </RadarChart>
                </ResponsiveContainer>
            </div>
          </div>
       </div>
    </div>
  );
};

import { supabase } from '../lib/supabase';
import { CharacterData, InjuryDefinition, TimeUnit, Ability } from '../types';
import { DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from '../constants';

// Helper to normalize bonuses from {stat, value} to {stat, val}
const normalizeBonuses = (items: any[]) => {
  if (!Array.isArray(items)) return [];
  return items.map(item => ({
    ...item,
    bonuses: (item.bonuses || []).map((b: any) => ({
      stat: (b.stat || 'phys').toLowerCase().trim(),
      val: b.val !== undefined ? b.val : (b.value !== undefined ? b.value : 0)
    }))
  }));
};

// Helper to normalize cooldowns/durations and descriptions
const normalizeAbilities = (abilities: any[]) => {
  if (!Array.isArray(abilities)) return [];
  const normalizedItems = normalizeBonuses(abilities);
  return normalizedItems.map((ab: any) => ({
    ...ab,
    // Map 'limits' object to flat limit/limit_unit if present in new JSON
    limit: ab.limit !== undefined ? ab.limit : (ab.limits?.value || 0),
    limit_unit: ab.limit_unit !== undefined ? ab.limit_unit : (ab.limits?.unit || ''),
    // Map cooldown object
    cd: ab.cd !== undefined ? ab.cd : (ab.cooldown?.value || 0),
    cd_unit: ab.cd_unit !== undefined ? ab.cd_unit : (ab.cooldown?.unit || ''),
    // Map duration object
    dur: ab.dur !== undefined ? ab.dur : (ab.duration?.value || 0),
    dur_unit: ab.dur_unit !== undefined ? ab.dur_unit : (ab.duration?.unit || ''),
    // Map description object to flat desc_lore/desc_mech with robust fallbacks
    desc_lore: ab.desc_lore !== undefined ? ab.desc_lore : (ab.desc?.lore || ''),
    desc_mech: ab.desc_mech !== undefined ? ab.desc_mech : (ab.desc?.mech || '')
  }));
};

const normalizeItems = (items: any[]) => {
    if (!Array.isArray(items)) return [];
    const normalized = normalizeBonuses(items);
    return normalized.map((item: any) => ({
        ...item,
        desc_lore: item.desc_lore !== undefined ? item.desc_lore : (item.desc?.lore || ''),
        desc_mech: item.desc_mech !== undefined ? item.desc_mech : (item.desc?.mech || '')
    }));
}

export const getBasicActions = async (): Promise<Ability[]> => {
    try {
        const { data } = await supabase.from('basic_actions').select('*');
        if (!data || data.length === 0) return [];

        // Map DB rows to Ability objects
        return data.map((row: any) => ({
            name: row.name || "Action",
            bonuses: row.bonuses || [],
            tags: row.tags || [],
            desc_lore: row.desc_lore || "",
            desc_mech: row.desc_mech || "",
            cd: row.cd || 0,
            cd_unit: row.cd_unit || "",
            dur: row.dur || 0,
            dur_unit: row.dur_unit || "",
            limit: row.limit || 0,
            limit_unit: row.limit_unit || ""
        }));
    } catch (e) {
        console.warn("Failed to fetch basic actions", e);
        return [];
    }
};

export const saveBasicActions = async (actions: Ability[]) => {
    // Clear existing table and insert new
    // Note: In a real prod app, you might want to upsert by ID, but for config this is fine.
    const { error: delError } = await supabase.from('basic_actions').delete().neq('id', 0); // Delete all
    if (delError) console.warn("Error clearing basic actions", delError);

    if (actions.length > 0) {
        const { error } = await supabase.from('basic_actions').insert(actions);
        if (error) throw new Error(error.message);
    }
};

export const getAllCharacters = async (): Promise<CharacterData[]> => {
  try {
    console.log('Fetching characters...');

    // Fetch Basic Actions concurrently
    const [charRes, basicActions] = await Promise.all([
        supabase.from('characters').select('*'),
        getBasicActions()
    ]);

    const { data, error } = charRes;

    if (error) {
      console.error("Supabase fetch error (characters):", error);
      return [];
    }

    if (!data) return [];

    const validChars: CharacterData[] = [];

    data.forEach((row: any) => {
      let charData = row.data || row;
      if (!charData.id) charData.id = row.id;

      if (!charData.profile) {
          return; 
      }

      // --- HYDRATION & DEFAULTS ---

      // 1. Profile & Meta
      if (!charData.profile.currencies) charData.profile.currencies = { juhe: 0, jumi: 0 };
      if (!charData.meta) charData.meta = { uid: 'system', owner_link: '', avatar_url: '', save_status: true };
      if (!charData.stats) charData.stats = { phys: 0, magic: 0, unique: 0 };

      // Initialize standardized arrays if missing
      if (!charData.passives) charData.passives = [];

      // 2. Extract from "tabs" structure if present (New JSON format)
      if (charData.tabs) {
          const tabs = charData.tabs;

          // Equipment Mapping
          if (tabs.equipment) {
              charData.equipment = {
                  wearable: normalizeItems(tabs.equipment.wearable),
                  usable: normalizeItems(tabs.equipment.weapons), // Map 'weapons' -> 'usable'
                  inventory: normalizeItems(tabs.equipment.backpack) // Map 'backpack' -> 'inventory'
              };
          }

          // Abilities Mapping
          if (tabs.abilities && Array.isArray(tabs.abilities.schools)) {
              charData.ability_groups = tabs.abilities.schools.map((school: any) => ({
                  ...school,
                  abilities: normalizeAbilities(school.abilities)
              }));
          }

          // Passives & Debuffs Mapping - Clear current passives to rebuild from tabs
          charData.passives = [];

          if (tabs.passives && Array.isArray(tabs.passives.groups)) {
              // Map standard passives
              const pGroups = tabs.passives.groups.map((g: any) => ({
                  ...g,
                  group_name: g.group_name || g.name || "Passives", // Ensure name
                  tags: g.tags || [],
                  items: normalizeItems(g.abilities || g.items), // Handle if named 'abilities' in JSON
                  is_flaw_group: false
              }));
              charData.passives.push(...pGroups);
          }

          if (tabs.debuffs && Array.isArray(tabs.debuffs.groups)) {
              // Map debuffs
              const dGroups = tabs.debuffs.groups.map((g: any) => ({
                  ...g,
                  group_name: g.group_name || g.name || "Debuffs", // Ensure name
                  tags: g.tags || [],
                  items: normalizeItems(g.abilities || g.items),
                  is_flaw_group: true
              }));
              charData.passives.push(...dGroups);
          }

          // Medcard
          if (tabs.medcard) {
              charData.medcard = tabs.medcard;
          }
      } 
      // 2b. Handle case where JSON has root-level 'passives' and 'debuffs' arrays (no 'tabs')
      else {
          // If we have a 'debuffs' array at root, merge it into passives
          if (charData.debuffs && Array.isArray(charData.debuffs)) {
              const rootDebuffs = charData.debuffs.map((g: any) => ({
                  ...g,
                  group_name: g.group_name || g.name || "Debuffs",
                  tags: g.tags || [],
                  items: normalizeItems(g.abilities || g.items),
                  is_flaw_group: true
              }));
              charData.passives.push(...rootDebuffs);
          }

          // Ensure existing passives have group_name
          if (Array.isArray(charData.passives)) {
              charData.passives = charData.passives.map((g: any) => ({
                  ...g,
                  group_name: g.group_name || g.name || "Group",
                  items: normalizeItems(g.items || g.abilities || [])
              }));
          }
      }

      // 3. Final Fallbacks for empty arrays
      if (!charData.equipment) charData.equipment = { usable: [], wearable: [], inventory: [] };
      if (!Array.isArray(charData.equipment.wearable)) charData.equipment.wearable = [];
      if (!Array.isArray(charData.equipment.usable)) charData.equipment.usable = [];
      if (!Array.isArray(charData.equipment.inventory)) charData.equipment.inventory = [];

      if (!Array.isArray(charData.ability_groups)) charData.ability_groups = [];
      if (!Array.isArray(charData.passives)) charData.passives = [];
      if (!Array.isArray(charData.resources)) charData.resources = [];

      if (!charData.medcard) charData.medcard = { injuries: [], conditions: [] };
      if (!Array.isArray(charData.medcard.injuries)) charData.medcard.injuries = [];
      if (!Array.isArray(charData.medcard.conditions)) charData.medcard.conditions = [];

      // --- INJECT BASIC ACTIONS ---
      // Check if "Базовые Действия" group already exists. If not, inject it.
      if (basicActions.length > 0) {
          const hasBasicGroup = charData.ability_groups.some((g: any) => g.name === "Базовые Действия");
          if (!hasBasicGroup) {
              charData.ability_groups.unshift({
                  name: "Базовые Действия",
                  tags: [],
                  abilities: basicActions,
                  is_hidden: true // Hidden by default as requested
              });
          }
      }

      validChars.push(charData as CharacterData);
    });

    return validChars;
  } catch (error) {
    console.warn("Could not fetch characters.", error);
    return [];
  }
};

export const saveCharacter = async (char: CharacterData) => {
  if (!char.id) {
    throw new Error("Critical Error: Character ID missing before save attempt.");
  }

  // When saving, we keep the flat structure used by the App state for simplicity, 
  // or we could reconstruct the 'tabs' object. For now, we save the flat structure
  // which the parser above acts as a migration/adapter for.

  const payload = { ...char };
  // @ts-ignore
  delete payload.identity; 
  // @ts-ignore
  delete payload.med_card;
  // @ts-ignore
  delete payload.tabs; // We save the flattened version to avoid confusion or double data
  // @ts-ignore
  delete payload.debuffs; // We save debuffs merged into passives

  const { data, error } = await supabase
    .from('characters')
    .upsert({ 
      id: char.id, 
      data: payload 
    })
    .select();

  if (error) {
    console.error("Supabase Save Error:", error);
    throw new Error(`Database Error: ${error.message}`);
  }

  return true;
};

export const deleteCharacter = async (id: string) => {
  const { error } = await supabase.from('characters').delete().eq('id', id);
  if (error) throw new Error(error.message);

  const { error: cascadeError } = await supabase
    .from('characters')
    .delete()
    .eq('data->meta->>master_id', id);

  if (cascadeError) console.error("Failed to cascade delete minions", cascadeError);
};

export const uploadAvatar = async (file: File): Promise<string> => {
  const MAX_SIZE = 10 * 1024 * 1024;
  if (file.size > MAX_SIZE) throw new Error("Файл слишком большой. Максимум 10 МБ.");

  const fileExt = file.name.split('.').pop();
  const fileName = `avatar_${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
  const filePath = `${fileName}`;

  const { error: uploadError } = await supabase.storage.from('Juul-D-Tracker').upload(filePath, file);
  if (uploadError) throw new Error("Ошибка при загрузке изображения.");

  const { data } = supabase.storage.from('Juul-D-Tracker').getPublicUrl(filePath);
  return data.publicUrl;
};

export const getGlobalTriggers = async (): Promise<Record<string, string>> => {
  try {
    const { data } = await supabase.from('triggers').select('tag, label');
    if (!data || data.length === 0) return { "Always": "Пассивно / Всегда" };
    const map: Record<string, string> = {};
    data.forEach((row: any) => { map[row.tag] = row.label; });
    return map;
  } catch (error) {
    return { "Always": "Пассивно / Всегда" };
  }
};

export const saveGlobalTriggers = async (triggers: Record<string, string>) => {
  const rows = Object.entries(triggers).map(([tag, label]) => ({ tag, label }));
  if (rows.length > 0) await supabase.from('triggers').upsert(rows);
};

export const getInjuries = async (): Promise<InjuryDefinition[]> => {
  try {
    const { data } = await supabase.from('injuries').select('*').order('type').order('value');
    if (!data || data.length === 0) return DEFAULT_INJURIES;
    return data as InjuryDefinition[];
  } catch (error) {
    return DEFAULT_INJURIES;
  }
};

export const saveInjuries = async (injuries: InjuryDefinition[]) => {
  if (injuries.length > 0) await supabase.from('injuries').upsert(injuries);
};

export const getTimeUnits = async (): Promise<TimeUnit[]> => {
  try {
    const { data } = await supabase.from('time_units').select('tag, label, battle');
    if (!data || data.length === 0) return DEFAULT_TIME_UNITS;
    return data.map((r: any) => ({ tag: r.tag || r.label, label: r.label, battle: r.battle || false }));
  } catch (error) {
    return DEFAULT_TIME_UNITS;
  }
};

export const saveTimeUnits = async (units: TimeUnit[]) => {
  const rows = units.map(u => ({ tag: u.tag, label: u.label, battle: u.battle }));
  if (rows.length > 0) await supabase.from('time_units').upsert(rows, { onConflict: 'tag' });
};

